import React, { useState, useEffect, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import {
  Grid, Card, CardContent, Typography, Box, Button, Avatar, Chip,
  Divider, IconButton, Table, TableBody, TableCell, TableContainer,
  TableHead, TableRow, LinearProgress, List, ListItem, ListItemText,
  Tooltip, Stack, Badge, TextField, MenuItem, Dialog, DialogTitle,
  DialogContent, DialogActions, useTheme, alpha, Drawer, useMediaQuery,
  Zoom, Fade, Slide
} from "@mui/material";
import {
  Business, People, School, Assignment, TrendingUp, Assessment,
  Notifications, LightMode, DarkMode, Logout, Dashboard, Groups,
  Settings, CheckCircle, Cancel, Visibility, Search, Grade,
  CalendarToday, ChevronLeft, ChevronRight, Menu as MenuIcon,
  Add as AddIcon, Send as SendIcon, LibraryBooks, SupportAgent,
  Computer, Delete, Edit as EditIcon, Science, AccountBalance,
  EmojiEvents, Announcement, BarChart as BarChartIcon, Close,
  LockReset, Campaign, Public, Layers, AutoAwesome, Terminal,
  Radar, Insights, Security, Hub, Memory, Bolt,
} from "@mui/icons-material";
import {
  BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RTooltip,
  ResponsiveContainer, Cell, PieChart, Pie, Legend, LineChart, Line,
  AreaChart, Area
} from "recharts";
import { useAuth } from "../../context/AuthContext";
import { useColorMode } from "../../context/ThemeContext";
import { coursesAPI, usersAPI, departmentsAPI, announcementsAPI, researchAPI } from "../../services/api";

/* ── Design Tokens ────────────────────────────────────────────────── */
const THEME_G = {
  indigo: "linear-gradient(135deg, #6366f1 0%, #4f46e5 100%)",
  violet: "linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%)",
  cyan: "linear-gradient(135deg, #06b6d4 0%, #0891b2 100%)",
  rose: "linear-gradient(135deg, #f43f5e 0%, #e11d48 100%)",
  amber: "linear-gradient(135deg, #f59e0b 0%, #d97706 100%)",
  emerald: "linear-gradient(135deg, #10b981 0%, #059669 100%)",
  slate: "linear-gradient(135deg, #1e293b 0%, #0f172a 100%)",
};

const TABS = [
  { label: "Overview", icon: <Dashboard />, idx: 0 },
  { label: "Departments", icon: <Hub />, idx: 1 },
  { label: "Faculty", icon: <Security />, idx: 2 },
  { label: "Students", icon: <People />, idx: 3 },
  { label: "Courses", icon: <Layers />, idx: 4 },
  { label: "Research", icon: <Science />, idx: 5 },
  { label: "Announcements", icon: <Campaign />, idx: 6 },
];

/* ── Components ────────────────────────────────────────────────────── */

const GlassCard = ({ children, sx = {}, hover = true }) => {
  // eslint-disable-next-line no-unused-vars
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  return (
    <Card sx={{
      borderRadius: 6,
      background: isDark ? "rgba(15, 23, 42, 0.4)" : "rgba(255, 255, 255, 0.6)",
      backdropFilter: "blur(20px) saturate(180%)",
      border: isDark ? "1px solid rgba(255, 255, 255, 0.08)" : "1px solid rgba(255, 255, 255, 0.3)",
      boxShadow: isDark ? "0 8px 32px rgba(0, 0, 0, 0.3)" : "0 8px 32px rgba(99, 102, 241, 0.05)",
      transition: "all 0.4s cubic-bezier(0.4, 0, 0.2, 1)",
      overflow: "visible",
      "&:hover": hover ? {
        transform: "translateY(-6px)",
        boxShadow: isDark ? "0 20px 48px rgba(0, 0, 0, 0.5)" : "0 20px 48px rgba(99, 102, 241, 0.12)",
        borderColor: isDark ? "rgba(255, 255, 255, 0.15)" : "rgba(99, 102, 241, 0.3)",
      } : {},
      ...sx
    }}>
      {children}
    </Card>
  );
};

const IntelligenceStat = ({ label, value, icon, grad, trend, color }) => {
  const theme = useTheme();
  return (
    <GlassCard sx={{ p: 3, position: "relative", overflow: "hidden" }}>
      <Box sx={{ position: "absolute", top: -20, right: -20, width: 100, height: 100, borderRadius: "50%", background: grad, opacity: 0.05, filter: "blur(20px)" }} />
      <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", mb: 2 }}>
        <Box sx={{ width: 52, height: 52, borderRadius: 3.5, background: grad, display: "flex", alignItems: "center", justifyContent: "center", color: "white", boxShadow: `0 8px 24px ${alpha(color, 0.3)}` }}>
          {React.cloneElement(icon, { sx: { fontSize: 28 } })}
        </Box>
        {trend && (
          <Chip
            icon={<TrendingUp sx={{ fontSize: 14, color: "inherit !important" }} />}
            label={trend}
            size="small"
            sx={{
              bgcolor: alpha("#10b981", 0.1),
              color: "#10b981",
              fontWeight: 900,
              fontSize: "0.7rem",
              borderRadius: 2,
              border: "1px solid rgba(16, 185, 129, 0.2)"
            }}
          />
        )}
      </Box>
      <Typography variant="h3" fontWeight={1000} sx={{ letterSpacing: -2, mb: 0.5, fontFamily: "'Outfit', sans-serif" }}>
        {value}
      </Typography>
      <Typography variant="caption" color="text.secondary" fontWeight={800} sx={{ textTransform: "uppercase", letterSpacing: 1.5, opacity: 0.7 }}>
        {label}
      </Typography>
    </GlassCard>
  );
};

/* ── Main Dashboard ────────────────────────────────────────────────── */

export default function FacultyDashboard() {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const { mode, toggleColorMode } = useColorMode();
  const theme = useTheme();
  const isDark = theme.palette.mode === "dark";
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));

  // Framework States
  const [activeTab, setActiveTab] = useState(0);
  const [sidebarOpen, setSidebarOpen] = useState(true);
  // eslint-disable-next-line no-unused-vars
  const [loading, setLoading] = useState(true);

  // Persistence States (MongoDB)
  const [courses, setCourses] = useState([]);
  const [faculty, setFaculty] = useState([]);
  const [students, setStudents] = useState([]);
  const [announcements, setAnnouncements] = useState([]);
  const [research, setResearch] = useState([]);
  const [departments, setDepartments] = useState([]);

  // Operational States
  const [addCourseOpen, setAddCourseOpen] = useState(false);
  const [newCourse, setNewCourse] = useState({ code: "", name: "", description: "", credits: 3, year: 1, semester: 1, instructorId: "", schedule: "", room: "", maxStudents: 40 });

  /* ── Data Acquisition ────────────────────────────────────────────── */
  useEffect(() => {
    if (!user?.id) return;

    const syncMatrix = async () => {
      setLoading(true);
      try {
        const dept = user?.department || "";
        const [resCourses, resFaculty, resStudents, resDepts, resAnn, resRes] = await Promise.all([
          coursesAPI.getAll({ department: dept }),
          usersAPI.getAll({ role: "teacher" }),
          usersAPI.getAll({ role: "student" }),
          departmentsAPI.getAll(),
          announcementsAPI.getAll(),
          researchAPI.getAll(),
        ]);

        setCourses(resCourses.data || []);
        setFaculty(resFaculty.data || []);
        setStudents(resStudents.data || []);
        setDepartments(resDepts.data || []);
        setAnnouncements(resAnn.data || []);
        setResearch(resRes.data || []);
      } catch (error) {
        console.error("Neural Sync Error:", error);
      } finally {
        setLoading(false);
      }
    };

    syncMatrix();
  }, [user?.id, user?.department]);

  /* ── Aggregation Logic ───────────────────────────────────────────── */
  const metrics = useMemo(() => {
    const totalStudents = students.length;
    // Calculate real avg GPA if students have GPA data
    const validGpas = students.filter(s => s.gpa).map(s => s.gpa);
    const avgGpa = validGpas.length > 0 ? (validGpas.reduce((a, b) => a + b, 0) / validGpas.length).toFixed(2) : "3.75";

    const activeResearch = research.filter(r => r.status === "Active").length;
    const courseCapacity = courses.reduce((acc, c) => acc + (c.maxStudents || 40), 0);
    const enrollmentRate = totalStudents > 0 && courseCapacity > 0 ? Math.round((totalStudents / courseCapacity) * 100) : 0;

    return { totalStudents, avgGpa, activeResearch, enrollmentRate };
  }, [students, research, courses]);

  // Aggregate enrollment per department for charts
  const enrollmentByDept = useMemo(() => {
    const counts = {};
    students.forEach(s => {
      const d = s.department || "General";
      counts[d] = (counts[d] || 0) + 1;
    });
    return Object.keys(counts).map(name => ({ name, value: counts[name] }));
  }, [students]);

  /* ── Sidebar Component ───────────────────────────────────────────── */
  const CommandSidebar = () => (
    <Box sx={{
      width: sidebarOpen ? 280 : 88,
      height: "100vh",
      position: "fixed",
      left: 0, top: 0,
      background: isDark ? "rgba(10, 15, 30, 0.95)" : "rgba(255, 255, 255, 0.98)",
      backdropFilter: "blur(40px)",
      borderRight: `1px solid ${isDark ? "rgba(255,255,255,0.05)" : "rgba(99,102,241,0.1)"}`,
      boxShadow: "10px 0 40px rgba(0,0,0,0.1)",
      display: "flex", flexDirection: "column",
      transition: "width 0.4s cubic-bezier(0.4, 0, 0.2, 1)",
      zIndex: 1300,
    }}>
      <Box sx={{ p: 3, display: "flex", alignItems: "center", justifyContent: sidebarOpen ? "space-between" : "center", minHeight: 100 }}>
        {sidebarOpen && (
          <Fade in>
            <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              <Box sx={{ width: 44, height: 44, borderRadius: 3, background: THEME_G.indigo, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: `0 8px 20px ${alpha("#6366f1", 0.4)}` }}>
                <Terminal sx={{ color: "white", fontSize: 24 }} />
              </Box>
              <Box>
                <Typography variant="subtitle1" fontWeight={1000} sx={{ letterSpacing: -0.5, lineHeight: 1.2 }}>DASHBOARD</Typography>
                <Typography variant="caption" sx={{ opacity: 0.5, fontWeight: 800, textTransform: "uppercase", fontSize: "0.65rem", letterSpacing: 1.5 }}>Department Command</Typography>
              </Box>
            </Box>
          </Fade>
        )}
        <IconButton onClick={() => setSidebarOpen(!sidebarOpen)} sx={{ bgcolor: alpha(theme.palette.primary.main, 0.05), color: theme.palette.primary.main }}>
          {sidebarOpen ? <ChevronLeft /> : <MenuIcon />}
        </IconButton>
      </Box>

      {sidebarOpen && (
        <Box sx={{ px: 2, mb: 4 }}>
          <Box sx={{ p: 2, borderRadius: 5, background: isDark ? "rgba(255,255,255,0.03)" : "rgba(99,102,241,0.05)", border: `1px solid ${isDark ? "rgba(255,255,255,0.05)" : "rgba(99,102,241,0.1)"}` }}>
            <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
              <Badge overlap="circular" anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }} variant="dot" color="success">
                <Avatar sx={{ width: 44, height: 44, background: THEME_G.indigo, fontWeight: 900 }}>{user?.name?.[0]}</Avatar>
              </Badge>
              <Box sx={{ minWidth: 0 }}>
                <Typography variant="subtitle2" fontWeight={1000} noWrap>{user?.name || "Dean"}</Typography>
                <Typography variant="caption" sx={{ opacity: 0.6, fontWeight: 700, textTransform: "uppercase", fontSize: "0.6rem" }}>{user?.department || "General"} Department</Typography>
              </Box>
            </Box>
          </Box>
        </Box>
      )}

      <List sx={{ px: 2, flexGrow: 1, overflowY: "auto", py: 0 }}>
        {TABS.map(item => (
          <ListItem key={item.idx} disablePadding sx={{ mb: 1 }}>
            <Tooltip title={!sidebarOpen ? item.label : ""} placement="right">
              <Button
                fullWidth
                onClick={() => setActiveTab(item.idx)}
                startIcon={item.icon}
                sx={{
                  justifyContent: sidebarOpen ? "flex-start" : "center",
                  px: sidebarOpen ? 2.5 : 0, py: 1.8, borderRadius: 4, minWidth: 0,
                  color: activeTab === item.idx ? "white" : (isDark ? "rgba(255,255,255,0.5)" : "#64748b"),
                  background: activeTab === item.idx ? THEME_G.indigo : "transparent",
                  boxShadow: activeTab === item.idx ? `0 8px 24px ${alpha("#6366f1", 0.4)}` : "none",
                  "& .MuiButton-startIcon": { mr: sidebarOpen ? 2 : 0, ml: 0 },
                  "&:hover": { background: activeTab === item.idx ? THEME_G.indigo : (isDark ? "rgba(255,255,255,0.05)" : "rgba(99,102,241,0.08)") },
                  transition: "all 0.3s",
                }}
              >
                {sidebarOpen && <Typography variant="body2" fontWeight={activeTab === item.idx ? 1000 : 700}>{item.label}</Typography>}
              </Button>
            </Tooltip>
          </ListItem>
        ))}
      </List>

      <Box sx={{ p: 2 }}>
        <Divider sx={{ mb: 2, opacity: 0.1 }} />
        <Button
          fullWidth
          onClick={toggleColorMode}
          startIcon={mode === "dark" ? <LightMode /> : <DarkMode />}
          sx={{ justifyContent: sidebarOpen ? "flex-start" : "center", color: isDark ? "rgba(255,255,255,0.5)" : "#64748b", py: 1.5, borderRadius: 4, "& .MuiButton-startIcon": { mr: sidebarOpen ? 2 : 0 } }}
        >
          {sidebarOpen && <Typography variant="body2" fontWeight={700}>{mode === "dark" ? "Light Mode" : "Dark Mode"}</Typography>}
        </Button>
        <Button
          fullWidth
          onClick={() => { logout(); navigate("/"); }}
          startIcon={<Logout />}
          sx={{ justifyContent: sidebarOpen ? "flex-start" : "center", color: "#f43f5e", mt: 1, py: 1.5, borderRadius: 4, fontWeight: 900, "& .MuiButton-startIcon": { mr: sidebarOpen ? 2 : 0 }, "&:hover": { bgcolor: alpha("#f43f5e", 0.1) } }}
        >
          {sidebarOpen && <Typography variant="body2" fontWeight={900}>Logout</Typography>}
        </Button>
      </Box>
    </Box>
  );

  /* ── Dashboard Views ─────────────────────────────────────────────── */

  const OverviewTab = () => (
    <Box>
      <Box sx={{ mb: 6 }}>
        <Typography variant="h2" fontWeight={1000} sx={{ letterSpacing: -3, lineHeight: 1, mb: 1, color: isDark ? "white" : "#0f172a" }}>
          Command<span style={{ color: alpha(theme.palette.primary.main, 0.7) }}>.</span>Center
        </Typography>
        <Typography variant="subtitle1" color="text.secondary" fontWeight={700} sx={{ letterSpacing: 1.5, opacity: 0.7 }}>
          UNIT: {user?.department?.toUpperCase() || "ACADEMIC"} DEPT &nbsp; // &nbsp; STATUS: ONLINE
        </Typography>
      </Box>

      <Grid container spacing={3} sx={{ mb: 6 }}>
        <Grid item xs={12} sm={6} md={3}>
          <IntelligenceStat label="Active Faculty" value={faculty.length} icon={<Security />} grad={THEME_G.indigo} trend={`${faculty.length > 0 ? "+1" : "0"} node`} color="#6366f1" />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <IntelligenceStat label="Enrolled Students" value={students.length} icon={<People />} grad={THEME_G.emerald} trend="LINKED" color="#10b981" />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <IntelligenceStat label="Course Modules" value={courses.length} icon={<Layers />} grad={THEME_G.amber} trend="ACTIVE" color="#f59e0b" />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <IntelligenceStat label="Average GPA" value={metrics.avgGpa} icon={<EmojiEvents />} grad={THEME_G.rose} trend="SYST-AVG" color="#f43f5e" />
        </Grid>
      </Grid>

      <Grid container spacing={4}>
        <Grid item xs={12} md={8}>
          <GlassCard sx={{ p: 4, height: "100%" }}>
            <Typography variant="h5" fontWeight={1000} sx={{ mb: 4 }}>Demographic Distribution</Typography>
            <Box sx={{ height: 350 }}>
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={enrollmentByDept}>
                  <CartesianGrid strokeDasharray="3 3" stroke={alpha("#94a3b8", 0.1)} vertical={false} />
                  <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: "#94a3b8", fontSize: 11, fontWeight: 700 }} />
                  <YAxis hide />
                  <RTooltip contentStyle={{ borderRadius: 20, background: isDark ? "#0f172a" : "white", border: "none" }} />
                  <Bar dataKey="value" fill={theme.palette.primary.main} radius={[10, 10, 0, 0]}>
                    {enrollmentByDept.map((entry, index) => (
                      <Cell key={`cell-${index}`} fill={Object.values(THEME_G)[index % 6]} />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </Box>
          </GlassCard>
        </Grid>
        <Grid item xs={12} md={4}>
          <GlassCard sx={{ p: 4, height: "100%" }}>
            <Typography variant="h5" fontWeight={1000} sx={{ mb: 4 }}>Latest Transmission</Typography>
            <Stack spacing={3}>
              {announcements.slice(0, 4).map((ann) => (
                <Box key={ann._id} sx={{ display: "flex", gap: 2 }}>
                  <Avatar sx={{ background: ann.priority === "high" ? THEME_G.rose : THEME_G.indigo, width: 40, height: 40 }}>
                    <Campaign />
                  </Avatar>
                  <Box sx={{ minWidth: 0 }}>
                    <Typography variant="subtitle2" fontWeight={1000} noWrap>{ann.title}</Typography>
                    <Typography variant="caption" color="text.secondary" sx={{ display: "-webkit-box", WebkitLineClamp: 2, WebkitBoxOrient: "vertical", overflow: "hidden" }}>{ann.body}</Typography>
                  </Box>
                </Box>
              ))}
              {announcements.length === 0 && <Typography variant="caption" sx={{ opacity: 0.5 }}>No data found in transmission buffer.</Typography>}
            </Stack>
          </GlassCard>
        </Grid>
      </Grid>
    </Box>
  );

  const DepartmentsTab = () => (
    <Box>
      <Typography variant="h4" fontWeight={1000} sx={{ letterSpacing: -1, mb: 4 }}>Sector Map: Departments</Typography>
      <Grid container spacing={3}>
        {departments.map((dept, i) => (
          <Grid item xs={12} md={4} key={dept._id || i}>
            <GlassCard sx={{ p: 3, height: "100%", borderTop: `6px solid ${dept.color || "#6366f1"}` }}>
              <Box sx={{ display: "flex", justifyContent: "space-between", mb: 2 }}>
                <Typography variant="h6" fontWeight={1000}>{dept.name}</Typography>
                <Chip label={dept.code} size="small" sx={{ fontWeight: 900, fontSize: "0.7rem", bgcolor: alpha(dept.color || "#6366f1", 0.1), color: dept.color || "#6366f1" }} />
              </Box>
              <Typography variant="caption" color="text.secondary" fontWeight={800}>FACULTY HEAD: {dept.headName || "DR. ALAN TURING"}</Typography>
              <Box sx={{ mt: 3, display: "flex", gap: 2 }}>
                <Box>
                  <Typography variant="body1" fontWeight={1000}>{students.filter(s => s.department === dept.name).length}</Typography>
                  <Typography variant="caption" color="text.secondary" fontWeight={700}>Students</Typography>
                </Box>
                <Box>
                  <Typography variant="body1" fontWeight={1000}>{faculty.filter(f => f.department === dept.name).length}</Typography>
                  <Typography variant="caption" color="text.secondary" fontWeight={700}>Faculty</Typography>
                </Box>
                <Box>
                  <Typography variant="body1" fontWeight={1000}>{courses.filter(c => c.department === dept.name).length}</Typography>
                  <Typography variant="caption" color="text.secondary" fontWeight={700}>Courses</Typography>
                </Box>
              </Box>
            </GlassCard>
          </Grid>
        ))}
      </Grid>
    </Box>
  );

  const FacultyTab = () => (
    <Box>
      <Typography variant="h4" fontWeight={1000} sx={{ letterSpacing: -1, mb: 4 }}>Faculty Corps</Typography>
      <GlassCard>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow sx={{ background: alpha(theme.palette.primary.main, 0.03) }}>
                {["Personnel", "Identification", "Designation", "Department", "Actions"].map(h => (
                  <TableCell key={h} sx={{ fontWeight: 900, color: "text.secondary", fontSize: "0.65rem", textTransform: "uppercase", letterSpacing: 2 }}>{h}</TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {faculty.map((f) => (
                <TableRow key={f._id} sx={{ "&:hover": { background: alpha(theme.palette.primary.main, 0.05) } }}>
                  <TableCell>
                    <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                      <Avatar sx={{ background: THEME_G.violet, fontWeight: 1000 }}>{f.name[0]}</Avatar>
                      <Box>
                        <Typography variant="subtitle2" fontWeight={1000}>{f.name}</Typography>
                        <Typography variant="caption" color="text.secondary">{f.email}</Typography>
                      </Box>
                    </Box>
                  </TableCell>
                  <TableCell sx={{ fontWeight: 800, fontFamily: "monospace" }}>{f.employeeId || "REF-SYNC"}</TableCell>
                  <TableCell>
                    <Chip label={f.position || "Professor"} size="small" sx={{ fontWeight: 900, bgcolor: alpha(theme.palette.secondary.main, 0.1), color: theme.palette.secondary.main }} />
                  </TableCell>
                  <TableCell sx={{ fontWeight: 700 }}>{f.department}</TableCell>
                  <TableCell>
                    <IconButton size="small" color="primary"><Visibility sx={{ fontSize: 18 }} /></IconButton>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </GlassCard>
    </Box>
  );

  const StudentsTab = () => (
    <Box>
      <Typography variant="h4" fontWeight={1000} sx={{ letterSpacing: -1, mb: 4 }}>Student Database</Typography>
      <GlassCard>
        <TableContainer>
          <Table>
            <TableHead>
              <TableRow sx={{ background: alpha(theme.palette.success.main, 0.03) }}>
                {["Student", "ID Hash", "Department", "Level", "GPA"].map(h => (
                  <TableCell key={h} sx={{ fontWeight: 900, color: "text.secondary", fontSize: "0.65rem", textTransform: "uppercase", letterSpacing: 2 }}>{h}</TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {students.map((s) => (
                <TableRow key={s._id} sx={{ "&:hover": { background: alpha(theme.palette.success.main, 0.05) } }}>
                  <TableCell>
                    <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                      <Avatar sx={{ background: THEME_G.emerald, fontWeight: 900 }}>{s.name[0]}</Avatar>
                      <Box>
                        <Typography variant="subtitle2" fontWeight={1000}>{s.name}</Typography>
                        <Typography variant="caption" color="text.secondary">{s.email}</Typography>
                      </Box>
                    </Box>
                  </TableCell>
                  <TableCell sx={{ fontWeight: 800, fontFamily: "monospace" }}>{s.studentId}</TableCell>
                  <TableCell sx={{ fontWeight: 700 }}>{s.department}</TableCell>
                  <TableCell sx={{ fontWeight: 700 }}>Year {s.year || "3"}</TableCell>
                  <TableCell sx={{ fontWeight: 1000, color: "success.main" }}>{s.gpa || "3.85"}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      </GlassCard>
    </Box>
  );

  // CoursesTab content is rendered inline in the return block below to prevent nested-component remount bug

  const ResearchTab = () => (
    <Box>
      <Typography variant="h4" fontWeight={1000} sx={{ letterSpacing: -1, mb: 4 }}>Research Nodes</Typography>
      <Grid container spacing={3}>
        {research.map((proj) => (
          <Grid item xs={12} md={4} key={proj._id}>
            <GlassCard sx={{ p: 3, height: "100%" }}>
              <Typography variant="h6" fontWeight={1000} sx={{ mb: 1 }}>{proj.title}</Typography>
              <Typography variant="caption" sx={{ fontWeight: 900, color: "primary.main", letterSpacing: 1.5 }}>PI: {proj.pi}</Typography>
              <Divider sx={{ my: 2, opacity: 0.1 }} />
              <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                <Typography variant="body2" fontWeight={1000} color="success.main">${proj.grant?.toLocaleString()}</Typography>
                <Chip label={proj.status} size="small" sx={{ fontWeight: 900, fontSize: "0.6rem" }} />
              </Box>
              <Typography variant="caption" sx={{ display: "block", mt: 2, opacity: 0.5 }}>DEPT: {proj.department}</Typography>
            </GlassCard>
          </Grid>
        ))}
        {research.length === 0 && <Typography variant="h6" sx={{ opacity: 0.5, textAlign: "center", width: "100%", py: 10 }}>No research nodes detected in this sector.</Typography>}
      </Grid>
    </Box>
  );

  const AnnouncementsTab = () => (
    <Box>
      <Typography variant="h4" fontWeight={1000} sx={{ letterSpacing: -1, mb: 4 }}>Transmissions Buffer</Typography>
      <Stack spacing={3}>
        {announcements.map((ann) => (
          <GlassCard key={ann._id} sx={{ p: 3 }}>
            <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", mb: 2 }}>
              <Box>
                <Typography variant="h6" fontWeight={1000}>{ann.title}</Typography>
                <Typography variant="caption" color="text.secondary" fontWeight={800}>{new Date(ann.createdAt).toLocaleString()}</Typography>
              </Box>
              <Chip label={ann.priority?.toUpperCase()} size="small" color={ann.priority === "high" ? "error" : "primary"} sx={{ fontWeight: 1000 }} />
            </Box>
            <Typography variant="body1" sx={{ opacity: 0.8 }}>{ann.body}</Typography>
            <Box sx={{ mt: 3, display: "flex", gap: 2 }}>
              <Typography variant="caption" fontWeight={900} sx={{ opacity: 0.5 }}>POSTED BY: {ann.postedByName || "CORE-SYSTEM"}</Typography>
              <Typography variant="caption" fontWeight={900} sx={{ opacity: 0.5 }}>TARGET: {ann.targetAudience?.toUpperCase() || "ALL"}</Typography>
            </Box>
          </GlassCard>
        ))}
      </Stack>
    </Box>
  );

  /* ── Main Render ─────────────────────────────────────────────────── */

  const mainML = isMobile ? 0 : `${sidebarOpen ? 280 : 88}px`;

  return (
    <Box sx={{ display: "flex", minHeight: "100vh", background: isDark ? "#05060f" : "#f8fafc", overflow: "hidden" }}>
      <CommandSidebar />
      <Box component="main" sx={{
        flexGrow: 1, ml: mainML, transition: "margin 0.4s",
        height: "100vh", overflowY: "auto", p: { xs: 2, md: 6 }, zIndex: 1
      }}>
        <Fade in timeout={800}>
          <Box>
            {activeTab === 0 && <OverviewTab />}
            {activeTab === 1 && <DepartmentsTab />}
            {activeTab === 2 && <FacultyTab />}
            {activeTab === 3 && <StudentsTab />}
            {activeTab === 4 && (
              <Box>
                <Box sx={{ mb: 4, display: "flex", justifyContent: "space-between", alignItems: "center" }}>
                  <Typography variant="h4" fontWeight={1000} sx={{ letterSpacing: -1 }}>Course Modules</Typography>
                  <Button variant="contained" startIcon={<AddIcon />} onClick={() => setAddCourseOpen(true)} sx={{ borderRadius: 3, fontWeight: 900, background: THEME_G.indigo }}>Deploy Module</Button>
                </Box>
                <Grid container spacing={3}>
                  {courses.map((c) => (
                    <Grid item xs={12} md={4} key={c._id}>
                      <GlassCard sx={{ height: "100%", borderBottom: `4px solid ${c.status === "active" ? "#10b981" : "#f59e0b"}` }}>
                        <Box sx={{ p: 3 }}>
                          <Typography variant="h6" fontWeight={1000}>{c.name}</Typography>
                          <Typography variant="caption" sx={{ fontWeight: 900, opacity: 0.6, letterSpacing: 1 }}>{c.code?.toUpperCase()}</Typography>
                          <Stack spacing={2} sx={{ mt: 3 }}>
                            <Box sx={{ display: "flex", justifyContent: "space-between" }}>
                              <Typography variant="caption" fontWeight={800} color="text.secondary">INSTRUCTOR</Typography>
                              <Typography variant="body2" fontWeight={1000}>{c.instructorName}</Typography>
                            </Box>
                            <Box sx={{ display: "flex", justifyContent: "space-between" }}>
                              <Typography variant="caption" fontWeight={800} color="text.secondary">LOAD</Typography>
                              <Typography variant="body2" fontWeight={1000}>{c.enrolledStudents?.length || 0} / {c.maxStudents || 40}</Typography>
                            </Box>
                            <LinearProgress variant="determinate" value={((c.enrolledStudents?.length || 0) / (c.maxStudents || 40)) * 100} sx={{ height: 6, borderRadius: 3 }} />
                          </Stack>
                        </Box>
                      </GlassCard>
                    </Grid>
                  ))}
                </Grid>
              </Box>
            )}
            {activeTab === 5 && <ResearchTab />}
            {activeTab === 6 && <AnnouncementsTab />}
          </Box>
        </Fade>
      </Box>

      {/* Deploy Module Dialog */}
      <Dialog open={addCourseOpen} onClose={() => setAddCourseOpen(false)} PaperProps={{ sx: { background: isDark ? "rgba(15, 23, 42, 0.95)" : "white", backdropFilter: "blur(40px)", borderRadius: 8, p: 2, maxWidth: 500, width: "100%" } }}>
        <DialogTitle sx={{ fontWeight: 1000, fontSize: "1.8rem", textAlign: "center" }}>Deploy New Module</DialogTitle>
        <DialogContent>
          <Stack spacing={3} sx={{ mt: 2 }}>
            <TextField label="Module Title" fullWidth value={newCourse.name} onChange={(e) => setNewCourse({ ...newCourse, name: e.target.value })} sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }} autoFocus />
            <TextField label="Designation Code (e.g., CS101)" fullWidth value={newCourse.code} onChange={(e) => setNewCourse({ ...newCourse, code: e.target.value.toUpperCase() })} sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }} />
            <TextField label="Description" fullWidth multiline rows={2} value={newCourse.description} onChange={(e) => setNewCourse({ ...newCourse, description: e.target.value })} sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }} />
            <Grid container spacing={2}>
              <Grid item xs={4}>
                <TextField label="Credit Hours" type="number" fullWidth inputProps={{ min: 1, max: 6 }} value={newCourse.credits} onChange={(e) => setNewCourse({ ...newCourse, credits: Number(e.target.value) })} sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }} />
              </Grid>
              <Grid item xs={4}>
                <TextField label="Year" select fullWidth value={newCourse.year} onChange={(e) => setNewCourse({ ...newCourse, year: Number(e.target.value) })} sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }}>
                  {[1, 2, 3, 4].map(y => <MenuItem key={y} value={y}>Year {y}</MenuItem>)}
                </TextField>
              </Grid>
              <Grid item xs={4}>
                <TextField label="Semester" select fullWidth value={newCourse.semester} onChange={(e) => setNewCourse({ ...newCourse, semester: Number(e.target.value) })} sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }}>
                  <MenuItem value={1}>Semester 1</MenuItem>
                  <MenuItem value={2}>Semester 2</MenuItem>
                </TextField>
              </Grid>
            </Grid>
            <TextField
              label="Assign Instructor"
              select fullWidth
              value={newCourse.instructorId}
              onChange={(e) => {
                const sel = faculty.find(f => (f._id || f.id) === e.target.value);
                setNewCourse({ ...newCourse, instructorId: e.target.value, instructorName: sel?.name || "" });
              }}
              sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }}
            >
              <MenuItem value="">-- Not Assigned --</MenuItem>
              {faculty.map(f => <MenuItem key={f._id || f.id} value={f._id || f.id}>{f.name}</MenuItem>)}
            </TextField>
            <Grid container spacing={2}>
              <Grid item xs={6}>
                <TextField label="Schedule (e.g., MWF 9-10 AM)" fullWidth value={newCourse.schedule} onChange={(e) => setNewCourse({ ...newCourse, schedule: e.target.value })} sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }} />
              </Grid>
              <Grid item xs={6}>
                <TextField label="Room" fullWidth value={newCourse.room} onChange={(e) => setNewCourse({ ...newCourse, room: e.target.value })} sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }} />
              </Grid>
            </Grid>
            <TextField label="Max Students" type="number" fullWidth inputProps={{ min: 1 }} value={newCourse.maxStudents} onChange={(e) => setNewCourse({ ...newCourse, maxStudents: Number(e.target.value) })} sx={{ "& .MuiOutlinedInput-root": { borderRadius: 3 } }} />
          </Stack>
        </DialogContent>
        <DialogActions sx={{ p: 4, pt: 2, gap: 1 }}>
          <Button onClick={(e) => {
            e.preventDefault();
            setAddCourseOpen(false);
            setNewCourse({ code: "", name: "", credits: 3, year: 1, semester: 1 });
          }} sx={{ fontWeight: 900, borderRadius: 3 }}>Abort</Button>

          <Button variant="contained" disabled={!newCourse.name || !newCourse.code} onClick={async (e) => {
            e.preventDefault();
            try {
              const sel = faculty.find(f => (f._id || f.id) === newCourse.instructorId);
              const payload = {
                ...newCourse,
                department: user?.department || "General",
                instructor: newCourse.instructorId || user?.id || user?._id,
                instructorName: sel?.name || user?.name || "Unknown Instructor",
                status: "pending_college_approval",
              };
              const response = await coursesAPI.create(payload);
              setCourses(prev => [...prev, response.data]);
              window.alert("Course Module Deployed! Awaiting College Admin Approval.");
              setAddCourseOpen(false);
              setNewCourse({ code: "", name: "", description: "", credits: 3, year: 1, semester: 1, instructorId: "", schedule: "", room: "", maxStudents: 40 });
            } catch (err) {
              console.error(err);
              window.alert("Error Deploying Course: " + (err.response?.data?.message || err.message));
            }
          }} sx={{ background: THEME_G.indigo, borderRadius: 4, fontWeight: 1000, px: 4 }}>Deploy</Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
}

import React, { useState, useEffect, useMemo } from "react";
import { useNavigate } from "react-router-dom";
import {
    Container, Grid, Card, CardContent, Typography, Box, Button,
    Avatar, Chip, List, ListItem, ListItemText, Divider, LinearProgress,
    IconButton, Tab, Tabs, Badge, Tooltip, Table, TableBody, TableCell,
    TableContainer, TableHead, TableRow, TextField, MenuItem,
    Dialog, DialogTitle, DialogContent, DialogActions, FormControl,
    InputLabel, Select, Checkbox, FormControlLabel, Fade, Slide, Zoom,
    useTheme, alpha, Drawer, useMediaQuery, Stack
} from "@mui/material";
import {
    School, People, Assignment, Grade, Logout, EmojiEvents,
    LightMode, DarkMode, Notifications, Dashboard, Campaign,
    CheckCircle, AccessTime, TrendingUp, MenuBook, Star,
    CalendarMonth, Edit, Add, PersonOutline, BarChart,
    CloudUpload, FileDownload, Save, FilterList, Search,
    Visibility, Close, CheckCircleOutline, HighlightOff,
    ChevronLeft, ChevronRight, LibraryBooks, AssignmentInd,
    AccountBalance, SwapHoriz, Schedule, Menu as MenuIcon, LockReset,
    Terminal, Hub, Security, Layers, AutoAwesome
} from "@mui/icons-material";
import { useAuth } from "../../context/AuthContext";
import { useColorMode } from "../../context/ThemeContext";
import {
    coursesAPI, usersAPI, attendanceAPI,
    assignmentsAPI, announcementsAPI
} from "../../services/api";

// Import modular tabs
import { OverviewTab, AttendanceTab, RosterTab, GradeTab, AssignmentTab, ProfileTab } from "./tabs";

/* ── Design Tokens ────────────────────────────────────────────────── */
const THEME_G = {
    indigo: "linear-gradient(135deg, #6366f1 0%, #4f46e5 100%)",
    violet: "linear-gradient(135deg, #8b5cf6 0%, #7c3aed 100%)",
    cyan: "linear-gradient(135deg, #06b6d4 0%, #0891b2 100%)",
    rose: "linear-gradient(135deg, #f43f5e 0%, #e11d48 100%)",
    amber: "linear-gradient(135deg, #f59e0b 0%, #d97706 100%)",
    emerald: "linear-gradient(135deg, #10b981 0%, #059669 100%)",
    slate: "linear-gradient(135deg, #1e293b 0%, #0f172a 100%)",
};

// 13 Modules from the Lecturer Portal Roadmap
const NAV_ITEMS = [
    { label: "Overview", icon: <Dashboard />, idx: 0 }, // Not in the original list but necessary for landing
    { label: "Profile & Account", icon: <PersonOutline />, idx: 1 },
    { label: "Course Management", icon: <LibraryBooks />, idx: 2 },
    { label: "Course Materials", icon: <CloudUpload />, idx: 3 },
    { label: "Assignments & Assessments", icon: <Assignment />, idx: 4 },
    { label: "Attendance", icon: <CalendarMonth />, idx: 5 },
    { label: "Grading & Results", icon: <Grade />, idx: 6 },
    { label: "Communication", icon: <Campaign />, idx: 7 },
    { label: "Schedule & Calendar", icon: <Schedule />, idx: 8 },
    { label: "Student Management", icon: <People />, idx: 9 },
    { label: "Leave & Workload", icon: <AssignmentInd />, idx: 10 },
    { label: "Research", icon: <Hub />, idx: 11 },
    { label: "Reports & Analytics", icon: <BarChart />, idx: 12 },
    { label: "Notifications", icon: <Notifications />, idx: 13 },
];

/* ── Main Dashboard ────────────────────────────────────────────────── */

export default function TeacherDashboard() {
    const { user, logout } = useAuth();
    const navigate = useNavigate();
    const { mode, toggleColorMode } = useColorMode();
    const theme = useTheme();
    const isDark = theme.palette.mode === "dark";
    const isMobile = useMediaQuery(theme.breakpoints.down('md'));

    // Framework States
    const [activeTab, setActiveTab] = useState(0);
    const [sidebarOpen, setSidebarOpen] = useState(true);

    // Persistence States (MongoDB)
    const [courses, setCourses] = useState([]);
    const [students, setStudents] = useState([]);
    const [assignments, setAssignments] = useState([]);
    const [attendanceLog, setAttendanceLog] = useState({});
    const [recentComms, setRecentComms] = useState([]);

    // Operation States
    const [selectedCourseId, setSelectedCourseId] = useState("");
    const [attendanceDate, setAttendanceDate] = useState(new Date().toISOString().split('T')[0]);
    const [assignDialogOpen, setAssignDialogOpen] = useState(false);
    const [newAssignment, setNewAssignment] = useState({ title: "", description: "", deadline: "", maxMarks: 100 });

    /* ── Neural Sync ─────────────────────────────────────────────────── */
    useEffect(() => {
        if (!user?.id) return;

        const syncMatrix = async () => {
            setLoading(true);
            try {
                // Fetch courses where user is instructor
                const resCourses = await coursesAPI.getMyCourses();
                const courseList = resCourses.data || [];
                setCourses(courseList);

                if (courseList.length > 0 && !selectedCourseId) {
                    setSelectedCourseId(courseList[0]._id);
                }

                // Fetch students matching teacher's department or enrolled courses
                const resStudents = await usersAPI.getAll({ role: "student", department: user.department });
                setStudents(resStudents.data || []);

                // Fetch assignments
                const resAssign = await assignmentsAPI.getAll({ createdBy: user.id });
                setAssignments(resAssign.data || []);

                // Fetch Announcements
                const resAnn = await announcementsAPI.getAll({ department: user.department });
                setRecentComms(resAnn.data || []);

            } catch (error) {
                console.error("Neural Sync Error:", error);
            }
        };

        syncMatrix();
    }, [user?.id]);

    /* ── Aggregation Logic ───────────────────────────────────────────── */
    const metrics = useMemo(() => {
        const totalStudents = students.length;
        const activeCourses = courses.length;
        const totalAssignments = assignments.length;
        const validGpas = students.filter(s => s.gpa).map(s => s.gpa);
        const avgGpa = validGpas.length > 0 ? (validGpas.reduce((a, b) => a + b, 0) / validGpas.length).toFixed(2) : "3.82";

        return { totalStudents, activeCourses, totalAssignments, avgGpa };
    }, [students, courses, assignments]);

    const performanceData = useMemo(() => {
        return [
            { name: "Week 1", score: 72 }, { name: "Week 2", score: 78 },
            { name: "Week 3", score: 75 }, { name: "Week 4", score: 84 },
            { name: "Week 5", score: 82 }, { name: "Week 6", score: 88 },
        ];
    }, []);

    /* ── Handlers ────────────────────────────────────────────────────── */
    const handleSaveAttendance = async () => {
        if (!selectedCourseId) return;
        try {
            const studentsPayload = students.map(s => ({
                studentId: s._id,
                status: attendanceLog[s._id] ? "present" : "absent"
            }));

            await attendanceAPI.create({
                courseId: selectedCourseId,
                date: attendanceDate,
                students: studentsPayload,
                markedBy: user.id
            });
            alert("Attendance vectorized successfully.");
        } catch (error) {
            console.error("Attendance Error:", error);
        }
    };

    const handleDeployAssignment = async () => {
        if (!selectedCourseId || !newAssignment.title) return;
        try {
            await assignmentsAPI.create({
                ...newAssignment,
                courseId: selectedCourseId,
                createdBy: user.id
            });
            setAssignDialogOpen(false);
            setNewAssignment({ title: "", description: "", deadline: "", maxMarks: 100 });
            // Refresh
            const res = await assignmentsAPI.getAll({ createdBy: user.id });
            setAssignments(res.data);
        } catch (error) {
            console.error("Assignment Deploy Error:", error);
        }
    };

    /* ── Sidebar Component ───────────────────────────────────────────── */
    const CommandSidebar = () => (
        <Box sx={{
            width: sidebarOpen ? 280 : 88,
            height: "100vh",
            position: "fixed",
            left: 0, top: 0,
            background: isDark ? "rgba(10, 15, 30, 0.95)" : "rgba(255, 255, 255, 0.98)",
            backdropFilter: "blur(40px)",
            borderRight: `1px solid ${isDark ? "rgba(255,255,255,0.05)" : "rgba(99,102,241,0.1)"}`,
            display: "flex", flexDirection: "column",
            transition: "width 0.4s cubic-bezier(0.4, 0, 0.2, 1)",
            zIndex: 1300,
        }}>
            <Box sx={{ p: 3, display: "flex", alignItems: "center", justifyContent: sidebarOpen ? "space-between" : "center", minHeight: 100 }}>
                {sidebarOpen && (
                    <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                        <Box sx={{ width: 44, height: 44, borderRadius: 3, background: THEME_G.cyan, display: "flex", alignItems: "center", justifyContent: "center", boxShadow: `0 8px 20px ${alpha("#06b6d4", 0.4)}` }}>
                            <Terminal sx={{ color: "white", fontSize: 24 }} />
                        </Box>
                        <Box>
                            <Typography variant="subtitle1" fontWeight={1000} sx={{ letterSpacing: -0.5, lineHeight: 1.2 }}>DASHBOARD</Typography>
                            <Typography variant="caption" sx={{ opacity: 0.5, fontWeight: 800, textTransform: "uppercase", fontSize: "0.6rem", letterSpacing: 1.5 }}>Instructor Portal</Typography>
                        </Box>
                    </Box>
                )}
                <IconButton onClick={() => setSidebarOpen(!sidebarOpen)} sx={{ color: "primary.main" }}>
                    {sidebarOpen ? <ChevronLeft /> : <MenuIcon />}
                </IconButton>
            </Box>

            {sidebarOpen && (
                <Box sx={{ px: 2, mb: 4 }}>
                    <Box sx={{ p: 2, borderRadius: 5, background: isDark ? "rgba(255,255,255,0.03)" : "rgba(6, 182, 212, 0.05)", border: `1px solid ${isDark ? "rgba(255,255,255,0.05)" : "rgba(6, 182, 212, 0.1)"}` }}>
                        <Box sx={{ display: "flex", alignItems: "center", gap: 2 }}>
                            <Badge overlap="circular" anchorOrigin={{ vertical: 'bottom', horizontal: 'right' }} variant="dot" color="success">
                                <Avatar sx={{ width: 44, height: 44, background: THEME_G.cyan, fontWeight: 1000 }}>{user?.name?.[0]}</Avatar>
                            </Badge>
                            <Box sx={{ minWidth: 0 }}>
                                <Typography variant="subtitle2" fontWeight={1000} noWrap>{user?.name || "Instructor"}</Typography>
                                <Typography variant="caption" sx={{ opacity: 0.6, fontWeight: 700, textTransform: "uppercase", fontSize: "0.6rem" }}>{user?.department || "General"} Department</Typography>
                            </Box>
                        </Box>
                    </Box>
                </Box>
            )}

            <List sx={{ px: 2, flexGrow: 1, overflowY: "auto", py: 0 }}>
                {NAV_ITEMS.map(item => (
                    <ListItem key={item.idx} disablePadding sx={{ mb: 1 }}>
                        <Tooltip title={!sidebarOpen ? item.label : ""} placement="right">
                            <Button
                                fullWidth
                                onClick={() => setActiveTab(item.idx)}
                                startIcon={item.icon}
                                sx={{
                                    justifyContent: sidebarOpen ? "flex-start" : "center",
                                    px: sidebarOpen ? 2.5 : 0, py: 1.8, borderRadius: 4, minWidth: 0,
                                    color: activeTab === item.idx ? "white" : (isDark ? "rgba(255,255,255,0.5)" : "#64748b"),
                                    background: activeTab === item.idx ? THEME_G.cyan : "transparent",
                                    boxShadow: activeTab === item.idx ? `0 8px 24px ${alpha("#06b6d4", 0.4)}` : "none",
                                    "& .MuiButton-startIcon": { mr: sidebarOpen ? 2 : 0, ml: 0 },
                                    "&:hover": { background: activeTab === item.idx ? THEME_G.cyan : (isDark ? "rgba(255,255,255,0.05)" : "rgba(99,102,241,0.08)") },
                                    transition: "all 0.3s",
                                }}
                            >
                                {sidebarOpen && <Typography variant="body2" fontWeight={activeTab === item.idx ? 1000 : 700}>{item.label}</Typography>}
                            </Button>
                        </Tooltip>
                    </ListItem>
                ))}
            </List>

            <Box sx={{ p: 2 }}>
                <Divider sx={{ mb: 2, opacity: 0.1 }} />
                <Button fullWidth onClick={toggleColorMode} startIcon={mode === "dark" ? <LightMode /> : <DarkMode />} sx={{ color: "text.secondary", py: 1.5, borderRadius: 4 }}>
                    {sidebarOpen && <Typography variant="body2" fontWeight={700}>{mode === "dark" ? "Light Mode" : "Dark Mode"}</Typography>}
                </Button>
                <Button fullWidth onClick={() => { logout(); navigate("/"); }} startIcon={<Logout />} sx={{ color: "#f43f5e", mt: 1, py: 1.5, borderRadius: 4, fontWeight: 900 }}>
                    {sidebarOpen && <Typography variant="body2" fontWeight={900}>Logout</Typography>}
                </Button>
            </Box>
        </Box>
    );

    /* ── Main Render ─────────────────────────────────────────────────── */

    const mainML = isMobile ? 0 : `${sidebarOpen ? 280 : 88}px`;

    return (
        <Box sx={{ display: "flex", bgcolor: isDark ? "#05060f" : "#f8fafc", minHeight: "100vh", overflow: "hidden" }}>
            <CommandSidebar />
            <Box component="main" sx={{
                flexGrow: 1, ml: mainML, transition: "margin 0.4s",
                height: "100vh", overflowY: "auto", p: { xs: 2, md: 6 }, zIndex: 1
            }}>
                <Fade in timeout={800}>
                    <Box>
                        {activeTab === 0 && <OverviewTab user={user} metrics={metrics} performanceData={performanceData} recentComms={recentComms} />}
                        {activeTab === 1 && <ProfileTab user={user} />}
                        {activeTab === 4 && <AssignmentTab assignments={assignments} setAssignDialogOpen={setAssignDialogOpen} />}
                        {activeTab === 5 && (
                            <AttendanceTab
                                courses={courses} selectedCourseId={selectedCourseId} setSelectedCourseId={setSelectedCourseId}
                                attendanceDate={attendanceDate} setAttendanceDate={setAttendanceDate} handleSaveAttendance={handleSaveAttendance}
                                students={students} attendanceLog={attendanceLog} setAttendanceLog={setAttendanceLog}
                            />
                        )}
                        {activeTab === 6 && <GradeTab />}
                        {activeTab === 9 && <RosterTab students={students} />}
                        {/* Placeholder for un-implemented tabs */}
                        {![0, 1, 4, 5, 6, 9].includes(activeTab) && (
                            <Box sx={{ textAlign: "center", py: 20, opacity: 0.5 }}>
                                <Typography variant="h4" fontWeight={1000}>Module Offline</Typography>
                                <Typography variant="body1">This sector is currently undergoing engineering enhancements according to the Lecturer Roadmap Phase specs.</Typography>
                            </Box>
                        )}
                    </Box>
                </Fade>
            </Box>

            {/* Deployment Dialog */}
            <Dialog
                open={assignDialogOpen}
                onClose={() => setAssignDialogOpen(false)}
                PaperProps={{
                    sx: {
                        background: isDark ? "rgba(15, 23, 42, 0.95)" : "rgba(255, 255, 255, 0.98)",
                        backdropFilter: "blur(40px)",
                        borderRadius: 8, p: 2, maxWidth: 500, width: "100%",
                        border: "1px solid rgba(255,255,255,0.1)"
                    }
                }}
            >
                <DialogTitle sx={{ fontWeight: 1000, fontSize: "1.8rem", textAlign: "center", mb: 1 }}>Deploy Task Node</DialogTitle>
                <DialogContent>
                    <Stack spacing={3} sx={{ mt: 1 }}>
                        <TextField label="Node Title" variant="filled" fullWidth value={newAssignment.title} onChange={e => setNewAssignment({ ...newAssignment, title: e.target.value })} />
                        <TextField label="Subroutine Description" variant="filled" multiline rows={3} fullWidth value={newAssignment.description} onChange={e => setNewAssignment({ ...newAssignment, description: e.target.value })} />
                        <TextField label="Termination Date" variant="filled" type="date" fullWidth InputLabelProps={{ shrink: true }} value={newAssignment.deadline} onChange={e => setNewAssignment({ ...newAssignment, deadline: e.target.value })} />
                    </Stack>
                    <Box sx={{ mt: 3, p: 2, borderRadius: 3, bgcolor: alpha(theme.palette.secondary.main, 0.05), border: `1px dashed ${alpha(theme.palette.secondary.main, 0.3)}` }}>
                        <Typography variant="caption" sx={{ display: "block", color: "secondary.main", fontWeight: 1000, mb: 0.5 }}>AUTO-DEPROVISIONING</Typography>
                        <Typography variant="body2" sx={{ opacity: 0.7, fontSize: "0.75rem" }}>This node will be broadcast to all students in the <strong>{user?.department}</strong> sector.</Typography>
                    </Box>
                </DialogContent>
                <DialogActions sx={{ p: 4, pt: 0 }}>
                    <Button onClick={() => setAssignDialogOpen(false)} sx={{ fontWeight: 900, borderRadius: 3 }}>Abort</Button>
                    <Button variant="contained" onClick={handleDeployAssignment} sx={{ background: THEME_G.violet, borderRadius: 4, fontWeight: 1000, px: 4 }}>Initiate</Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
}

import React, { useState, useEffect } from "react";
import {
    Box, Grid, Card, CardContent, Typography, Button, Chip, Stack, Avatar,
    Dialog, DialogTitle, DialogContent, DialogActions, TextField, MenuItem,
    Table, TableBody, TableCell, TableContainer, TableHead, TableRow,
    IconButton, Tabs, Tab, Divider, alpha, LinearProgress, List,
    ListItem, ListItemIcon, ListItemText, Paper,
} from "@mui/material";
import {
    UploadFile, Description, FolderOpen, Event, Inventory,
    Add as AddIcon, CalendarToday, Article, Policy, BarChart as BudgetIcon,
    Archive, Announcement, MeetingRoom, Science, Construction,
    Close as CloseIcon, Download, Visibility, CheckCircle, DeleteOutline,
} from "@mui/icons-material";
import { useTheme } from "@mui/material/styles";
import { announcementsAPI, academicEventsAPI } from "../../../services/api";

const GRADIENTS = {
    premium: "linear-gradient(135deg, #2563eb 0%, #7c3aed 100%)",
    success: "linear-gradient(135deg, #10b981 0%, #059669 100%)",
    warning: "linear-gradient(135deg, #f59e0b 0%, #d97706 100%)",
    secondary: "linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%)",
};

const DOC_ICONS = {
    policy: <Policy />, circular: <Announcement />, minute: <Article />,
    form: <Description />, syllabus: <FolderOpen />, accreditation: <CheckCircle />,
};

export default function DocumentsTab({ department, user }) {
    const theme = useTheme();
    const isDark = theme.palette.mode === "dark";
    const [activeSubTab, setActiveSubTab] = useState(0);
    const [announcements, setAnnouncements] = useState([]);
    const [events, setEvents] = useState([]);
    const [documents, setDocuments] = useState([]);
    const [bookings, setBookings] = useState([]);
    const [equipment, setEquipment] = useState([]);
    // eslint-disable-next-line no-unused-vars
    const [budget, setBudget] = useState({ allocated: 50000, spent: 32500, currency: "JOD" });
    const [openAnnounce, setOpenAnnounce] = useState(false);
    const [openEvent, setOpenEvent] = useState(false);
    const [openDoc, setOpenDoc] = useState(false);
    const [openBooking, setOpenBooking] = useState(false);
    const [openEquip, setOpenEquip] = useState(false);
    const [newAnnounce, setNewAnnounce] = useState({ title: "", message: "", type: "circular" });
    const [newEvent, setNewEvent] = useState({ title: "", date: "", description: "", location: "" });
    const [newDoc, setNewDoc] = useState({ name: "", type: "policy", description: "" });
    const [newBooking, setNewBooking] = useState({ room: "", date: "", startTime: "09:00", endTime: "10:00", purpose: "" });
    const [newEquip, setNewEquip] = useState({ name: "", type: "Computer", location: "", status: "Available" });

    const glass = {
        background: isDark ? "rgba(15,23,42,0.6)" : "rgba(255,255,255,0.85)",
        backdropFilter: "blur(20px)",
        border: isDark ? "1px solid rgba(255,255,255,0.08)" : "1px solid rgba(255,255,255,0.5)",
        borderRadius: 16,
    };

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => { fetchAnnouncements(); fetchEvents(); }, [department]);

    const fetchAnnouncements = async () => {
        try {
            const res = await announcementsAPI.getAll({ department });
            setAnnouncements(res.data || []);
        } catch (e) { console.error(e); }
    };

    const fetchEvents = async () => {
        try {
            const res = await academicEventsAPI.getAll({ department });
            setEvents(res.data || []);
        } catch (e) { console.error(e); }
    };

    const handleAddAnnouncement = async () => {
        try {
            await announcementsAPI.create({ ...newAnnounce, department, createdBy: user?._id || user?.uid, date: new Date() });
            setOpenAnnounce(false);
            setNewAnnounce({ title: "", message: "", type: "circular" });
            fetchAnnouncements();
        } catch (e) { console.error(e); }
    };

    const handleAddEvent = async () => {
        try {
            await academicEventsAPI.create({ ...newEvent, department, createdBy: user?._id || user?.uid, type: "department" });
            setOpenEvent(false);
            setNewEvent({ title: "", date: "", description: "", location: "" });
            fetchEvents();
        } catch (e) { console.error(e); }
    };

    const handleAddDoc = () => {
        setDocuments(prev => [...prev, { ...newDoc, id: Date.now(), date: new Date().toLocaleDateString(), size: "—" }]);
        setOpenDoc(false);
        setNewDoc({ name: "", type: "policy", description: "" });
    };

    const handleAddBooking = () => {
        setBookings(prev => [...prev, { ...newBooking, id: Date.now(), status: "confirmed" }]);
        setOpenBooking(false);
        setNewBooking({ room: "", date: "", startTime: "09:00", endTime: "10:00", purpose: "" });
    };

    const handleAddEquip = () => {
        setEquipment(prev => [...prev, { ...newEquip, id: Date.now(), lastChecked: new Date().toLocaleDateString() }]);
        setOpenEquip(false);
        setNewEquip({ name: "", type: "Computer", location: "", status: "Available" });
    };

    const handleDeleteAnnouncement = async (id) => {
        try {
            await announcementsAPI.delete(id);
            fetchAnnouncements();
        } catch (e) { console.error(e); }
    };

    const subTabs = ["Announcements", "Events Calendar", "Documents & Forms", "Room Booking", "Equipment & Assets", "Budget Tracker"];
    // eslint-disable-next-line no-unused-vars
    const spent = budget.spent;
    // eslint-disable-next-line no-unused-vars
    const pct = Math.min(Math.round((spent / budget.allocated) * 100), 100);

    return (
        <Box>
            <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 4 }}>
                <Box>
                    <Typography variant="h5" fontWeight={1000} sx={{ letterSpacing: -0.5 }}>Documents & Resources</Typography>
                    <Typography variant="caption" color="text.secondary" fontWeight={800}>
                        ANNOUNCEMENTS • FORMS • EVENTS • EQUIPMENT • BUDGET
                    </Typography>
                </Box>
            </Box>

            <Tabs value={activeSubTab} onChange={(_, v) => setActiveSubTab(v)} variant="scrollable" scrollButtons="auto" sx={{
                mb: 3,
                "& .MuiTabs-indicator": { height: 3, borderRadius: 2 },
                "& .MuiTab-root": { fontWeight: 800, textTransform: "none", fontSize: "0.85rem" }
            }}>
                {subTabs.map((t, i) => <Tab key={i} label={t} />)}
            </Tabs>

            {/* Announcements */}
            {activeSubTab === 0 && (
                <Box>
                    <Box sx={{ display: "flex", justifyContent: "flex-end", mb: 3 }}>
                        <Button variant="contained" startIcon={<AddIcon />} onClick={() => setOpenAnnounce(true)}
                            sx={{ borderRadius: 2.5, fontWeight: 900, textTransform: "none", background: GRADIENTS.premium }}>
                            New Announcement
                        </Button>
                    </Box>
                    <Stack spacing={2}>
                        {announcements.map(a => (
                            <Card key={a._id} sx={{ ...glass }}>
                                <CardContent sx={{ p: 3 }}>
                                    <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                                        <Box sx={{ display: "flex", gap: 1.5, alignItems: "flex-start", flex: 1 }}>
                                            <Avatar sx={{ background: GRADIENTS.secondary, mt: 0.5 }}>
                                                {DOC_ICONS[a.type] || <Announcement />}
                                            </Avatar>
                                            <Box>
                                                <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 0.5 }}>
                                                    <Typography variant="subtitle1" fontWeight={900}>{a.title}</Typography>
                                                    <Chip label={a.type?.toUpperCase()} size="small" sx={{ fontWeight: 900, fontSize: "0.6rem", bgcolor: alpha("#6366f1", 0.1), color: "#6366f1" }} />
                                                </Box>
                                                <Typography variant="body2" color="text.secondary">{a.message}</Typography>
                                                <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: "block" }}>
                                                    {a.createdAt ? new Date(a.createdAt).toLocaleDateString() : "—"}
                                                </Typography>
                                            </Box>
                                        </Box>
                                        <IconButton size="small" color="error" onClick={() => handleDeleteAnnouncement(a._id)}>
                                            <DeleteOutline sx={{ fontSize: 18 }} />
                                        </IconButton>
                                    </Box>
                                </CardContent>
                            </Card>
                        ))}
                        {announcements.length === 0 && (
                            <Box sx={{ ...glass, p: 6, textAlign: "center" }}>
                                <Announcement sx={{ fontSize: 60, color: "text.secondary", opacity: 0.2, mb: 2 }} />
                                <Typography color="text.secondary" fontWeight={700}>No announcements yet</Typography>
                            </Box>
                        )}
                    </Stack>
                </Box>
            )}

            {/* Events Calendar */}
            {activeSubTab === 1 && (
                <Box>
                    <Box sx={{ display: "flex", justifyContent: "flex-end", mb: 3 }}>
                        <Button variant="contained" startIcon={<Event />} onClick={() => setOpenEvent(true)}
                            sx={{ borderRadius: 2.5, fontWeight: 900, textTransform: "none", background: GRADIENTS.success }}>
                            Add Event
                        </Button>
                    </Box>
                    <Grid container spacing={3}>
                        {events.map(ev => (
                            <Grid item xs={12} md={4} key={ev._id}>
                                <Card sx={{ ...glass }}>
                                    <CardContent sx={{ p: 3 }}>
                                        <Box sx={{ mb: 2, p: 2, background: GRADIENTS.premium, borderRadius: 3, textAlign: "center" }}>
                                            <Typography variant="h4" fontWeight={1000} color="white">
                                                {ev.date ? new Date(ev.date).getDate() : "—"}
                                            </Typography>
                                            <Typography variant="caption" color="rgba(255,255,255,0.7)" fontWeight={800}>
                                                {ev.date ? new Date(ev.date).toLocaleDateString("en-US", { month: "long", year: "numeric" }) : ""}
                                            </Typography>
                                        </Box>
                                        <Typography variant="subtitle1" fontWeight={900}>{ev.title}</Typography>
                                        <Typography variant="body2" color="text.secondary" sx={{ mb: 1 }}>{ev.description}</Typography>
                                        {ev.location && (
                                            <Chip icon={<MeetingRoom sx={{ fontSize: 14 }} />} label={ev.location} size="small" sx={{ fontWeight: 800 }} />
                                        )}
                                    </CardContent>
                                </Card>
                            </Grid>
                        ))}
                        {events.length === 0 && (
                            <Grid item xs={12}>
                                <Box sx={{ ...glass, p: 6, textAlign: "center" }}>
                                    <Event sx={{ fontSize: 60, color: "text.secondary", opacity: 0.2, mb: 2 }} />
                                    <Typography color="text.secondary" fontWeight={700}>No events scheduled</Typography>
                                </Box>
                            </Grid>
                        )}
                    </Grid>
                </Box>
            )}

            {/* Documents & Forms */}
            {activeSubTab === 2 && (
                <Box>
                    <Box sx={{ display: "flex", justifyContent: "flex-end", mb: 3 }}>
                        <Button variant="contained" startIcon={<UploadFile />} onClick={() => setOpenDoc(true)}
                            sx={{ borderRadius: 2.5, fontWeight: 900, textTransform: "none", background: GRADIENTS.secondary }}>
                            Upload Document
                        </Button>
                    </Box>
                    {/* Category legend */}
                    <Stack direction="row" spacing={1} sx={{ mb: 3, flexWrap: "wrap", gap: 1 }}>
                        {Object.keys(DOC_ICONS).map(type => (
                            <Chip key={type} label={type.charAt(0).toUpperCase() + type.slice(1)} size="small"
                                sx={{ fontWeight: 800, bgcolor: alpha("#6366f1", 0.08), color: "#6366f1" }} />
                        ))}
                    </Stack>
                    {documents.length === 0 ? (
                        <Box sx={{ ...glass, p: 6, textAlign: "center" }}>
                            <FolderOpen sx={{ fontSize: 60, color: "text.secondary", opacity: 0.2, mb: 2 }} />
                            <Typography color="text.secondary" fontWeight={700}>No department documents uploaded yet</Typography>
                        </Box>
                    ) : (
                        <TableContainer sx={{ ...glass }}>
                            <Table>
                                <TableHead>
                                    <TableRow>
                                        <TableCell sx={{ fontWeight: 900 }}>Document Name</TableCell>
                                        <TableCell sx={{ fontWeight: 900 }}>Type</TableCell>
                                        <TableCell sx={{ fontWeight: 900 }}>Date</TableCell>
                                        <TableCell align="right" sx={{ fontWeight: 900 }}>Actions</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {documents.map(doc => (
                                        <TableRow key={doc.id}>
                                            <TableCell>
                                                <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
                                                    <Avatar sx={{ width: 32, height: 32, background: GRADIENTS.secondary }}>{DOC_ICONS[doc.type]}</Avatar>
                                                    <Typography variant="body2" fontWeight={800}>{doc.name}</Typography>
                                                </Box>
                                            </TableCell>
                                            <TableCell><Chip label={doc.type} size="small" sx={{ fontWeight: 900 }} /></TableCell>
                                            <TableCell sx={{ fontWeight: 700 }}>{doc.date}</TableCell>
                                            <TableCell align="right">
                                                <Stack direction="row" spacing={1} justifyContent="flex-end">
                                                    <IconButton size="small"><Visibility sx={{ fontSize: 18 }} /></IconButton>
                                                    <IconButton size="small" color="error" onClick={() => setDocuments(prev => prev.filter(d => d.id !== doc.id))}>
                                                        <DeleteOutline sx={{ fontSize: 18 }} />
                                                    </IconButton>
                                                </Stack>
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>
                    )}
                </Box>
            )}

            {/* Room Booking */}
            {activeSubTab === 3 && (
                <Box>
                    <Box sx={{ display: "flex", justifyContent: "flex-end", mb: 3 }}>
                        <Button variant="contained" startIcon={<MeetingRoom />} onClick={() => setOpenBooking(true)}
                            sx={{ borderRadius: 2.5, fontWeight: 900, textTransform: "none", background: GRADIENTS.premium }}>
                            Book Room
                        </Button>
                    </Box>
                    {bookings.length === 0 ? (
                        <Box sx={{ ...glass, p: 6, textAlign: "center" }}>
                            <MeetingRoom sx={{ fontSize: 60, color: "text.secondary", opacity: 0.2, mb: 2 }} />
                            <Typography color="text.secondary" fontWeight={700}>No room bookings</Typography>
                        </Box>
                    ) : (
                        <TableContainer sx={{ ...glass }}>
                            <Table>
                                <TableHead>
                                    <TableRow>
                                        <TableCell sx={{ fontWeight: 900 }}>Room</TableCell>
                                        <TableCell sx={{ fontWeight: 900 }}>Date</TableCell>
                                        <TableCell sx={{ fontWeight: 900 }}>Time</TableCell>
                                        <TableCell sx={{ fontWeight: 900 }}>Purpose</TableCell>
                                        <TableCell sx={{ fontWeight: 900 }}>Status</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {bookings.map(b => (
                                        <TableRow key={b.id}>
                                            <TableCell fontWeight={800}>{b.room}</TableCell>
                                            <TableCell fontWeight={700}>{b.date}</TableCell>
                                            <TableCell fontWeight={700}>{b.startTime} – {b.endTime}</TableCell>
                                            <TableCell fontWeight={700}>{b.purpose}</TableCell>
                                            <TableCell>
                                                <Chip label="CONFIRMED" size="small" sx={{ bgcolor: alpha("#10b981", 0.1), color: "#10b981", fontWeight: 900 }} />
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>
                    )}
                </Box>
            )}

            {/* Equipment & Assets */}
            {activeSubTab === 4 && (
                <Box>
                    <Box sx={{ display: "flex", justifyContent: "flex-end", mb: 3 }}>
                        <Button variant="contained" startIcon={<Inventory />} onClick={() => setOpenEquip(true)}
                            sx={{ borderRadius: 2.5, fontWeight: 900, textTransform: "none", background: GRADIENTS.success }}>
                            Add Equipment
                        </Button>
                    </Box>
                    <Grid container spacing={3}>
                        {equipment.map(eq => (
                            <Grid item xs={12} sm={6} md={3} key={eq.id}>
                                <Card sx={{ ...glass }}>
                                    <CardContent sx={{ p: 3 }}>
                                        <Avatar sx={{ background: eq.status === "Available" ? GRADIENTS.success : GRADIENTS.warning, mb: 2 }}>
                                            {eq.type === "Computer" ? <Science /> : <Construction />}
                                        </Avatar>
                                        <Typography variant="subtitle1" fontWeight={900}>{eq.name}</Typography>
                                        <Typography variant="caption" color="text.secondary">{eq.type} • {eq.location}</Typography>
                                        <Box sx={{ mt: 2 }}>
                                            <Chip label={eq.status} size="small" sx={{
                                                fontWeight: 900,
                                                bgcolor: eq.status === "Available" ? alpha("#10b981", 0.1) : alpha("#f59e0b", 0.1),
                                                color: eq.status === "Available" ? "#10b981" : "#f59e0b",
                                            }} />
                                        </Box>
                                    </CardContent>
                                </Card>
                            </Grid>
                        ))}
                        {equipment.length === 0 && (
                            <Grid item xs={12}>
                                <Box sx={{ ...glass, p: 6, textAlign: "center" }}>
                                    <Inventory sx={{ fontSize: 60, color: "text.secondary", opacity: 0.2, mb: 2 }} />
                                    <Typography color="text.secondary" fontWeight={700}>No equipment tracked</Typography>
                                </Box>
                            </Grid>
                        )}
                    </Grid>
                </Box>
            )}

            {/* Budget Tracker */}
            {activeSubTab === 5 && (
                <Grid container spacing={3}>
                    <Grid item xs={12} md={4}>
                        <Card sx={{ ...glass, background: GRADIENTS.premium, color: "white" }}>
                            <CardContent sx={{ p: 4 }}>
                                <Typography variant="h6" fontWeight={900} gutterBottom>Budget Overview</Typography>
                                <Typography variant="h3" fontWeight={1000} sx={{ letterSpacing: -2, my: 2 }}>
                                    {budget.currency} {budget.allocated.toLocaleString()}
                                </Typography>
                                <Typography variant="caption" sx={{ opacity: 0.7, fontWeight: 800 }}>ANNUAL ALLOCATION</Typography>
                                <Divider sx={{ my: 2, borderColor: "rgba(255,255,255,0.1)" }} />
                                <Stack spacing={2}>
                                    {[
                                        { label: "Spent", value: budget.spent, color: "#f97316" },
                                        { label: "Remaining", value: budget.allocated - budget.spent, color: "#10b981" },
                                    ].map((item, i) => (
                                        <Box key={i} sx={{ display: "flex", justifyContent: "space-between" }}>
                                            <Typography variant="body2" fontWeight={700} sx={{ opacity: 0.7 }}>{item.label}</Typography>
                                            <Typography variant="body2" fontWeight={900} color={item.color}>
                                                {budget.currency} {item.value.toLocaleString()}
                                            </Typography>
                                        </Box>
                                    ))}
                                </Stack>
                            </CardContent>
                        </Card>
                    </Grid>
                    <Grid item xs={12} md={8}>
                        <Card sx={{ ...glass }}>
                            <CardContent sx={{ p: 4 }}>
                                <Typography variant="h6" fontWeight={900} gutterBottom>Expenditure by Category</Typography>
                                <Stack spacing={3} sx={{ mt: 2 }}>
                                    {[
                                        { label: "Salaries & Benefits", value: 18000, max: 25000 },
                                        { label: "Lab & Equipment", value: 7500, max: 12000 },
                                        { label: "Research Grants", value: 4000, max: 8000 },
                                        { label: "Events & Workshops", value: 2000, max: 3000 },
                                        { label: "Office & Admin", value: 1000, max: 2000 },
                                    ].map((cat, i) => {
                                        const catPct = Math.round((cat.value / cat.max) * 100);
                                        return (
                                            <Box key={i}>
                                                <Box sx={{ display: "flex", justifyContent: "space-between", mb: 1 }}>
                                                    <Typography variant="body2" fontWeight={800}>{cat.label}</Typography>
                                                    <Typography variant="body2" fontWeight={900} color={catPct > 85 ? "#ef4444" : "text.primary"}>
                                                        {budget.currency} {cat.value.toLocaleString()} / {cat.max.toLocaleString()}
                                                    </Typography>
                                                </Box>
                                                <LinearProgress variant="determinate" value={catPct} sx={{
                                                    height: 8, borderRadius: 4,
                                                    bgcolor: alpha("#94a3b8", isDark ? 0.2 : 0.15),
                                                    "& .MuiLinearProgress-bar": {
                                                        borderRadius: 4,
                                                        background: catPct > 85 ? GRADIENTS.danger : catPct > 65 ? GRADIENTS.warning : GRADIENTS.success
                                                    }
                                                }} />
                                            </Box>
                                        );
                                    })}
                                </Stack>
                            </CardContent>
                        </Card>
                    </Grid>
                </Grid>
            )}

            {/* Dialogs */}
            {/* Announcement */}
            <Dialog open={openAnnounce} onClose={() => setOpenAnnounce(false)} maxWidth="sm" fullWidth
                PaperProps={{ sx: { background: isDark ? "rgba(15,23,42,0.95)" : "rgba(255,255,255,0.98)", backdropFilter: "blur(20px)", borderRadius: 4 } }}>
                <DialogTitle fontWeight={1000}>New Announcement / Circular</DialogTitle>
                <DialogContent>
                    <Stack spacing={2.5} sx={{ mt: 1 }}>
                        <TextField select fullWidth label="Type" value={newAnnounce.type} onChange={e => setNewAnnounce({ ...newAnnounce, type: e.target.value })}>
                            <MenuItem value="circular">Circular</MenuItem>
                            <MenuItem value="minute">Meeting Minute</MenuItem>
                            <MenuItem value="policy">Policy Update</MenuItem>
                            <MenuItem value="event">Event Announcement</MenuItem>
                        </TextField>
                        <TextField fullWidth label="Title" value={newAnnounce.title} onChange={e => setNewAnnounce({ ...newAnnounce, title: e.target.value })} />
                        <TextField fullWidth multiline rows={4} label="Message / Content" value={newAnnounce.message} onChange={e => setNewAnnounce({ ...newAnnounce, message: e.target.value })} />
                    </Stack>
                </DialogContent>
                <DialogActions sx={{ p: 3 }}>
                    <Button onClick={() => setOpenAnnounce(false)} sx={{ fontWeight: 800 }}>Cancel</Button>
                    <Button onClick={handleAddAnnouncement} variant="contained" sx={{ borderRadius: 2, fontWeight: 900, background: GRADIENTS.premium }}>Publish</Button>
                </DialogActions>
            </Dialog>

            {/* Event */}
            <Dialog open={openEvent} onClose={() => setOpenEvent(false)} maxWidth="sm" fullWidth
                PaperProps={{ sx: { background: isDark ? "rgba(15,23,42,0.95)" : "rgba(255,255,255,0.98)", backdropFilter: "blur(20px)", borderRadius: 4 } }}>
                <DialogTitle fontWeight={1000}>Add Department Event</DialogTitle>
                <DialogContent>
                    <Stack spacing={2.5} sx={{ mt: 1 }}>
                        <TextField fullWidth label="Event Title" value={newEvent.title} onChange={e => setNewEvent({ ...newEvent, title: e.target.value })} />
                        <TextField fullWidth type="date" label="Date" InputLabelProps={{ shrink: true }} value={newEvent.date} onChange={e => setNewEvent({ ...newEvent, date: e.target.value })} />
                        <TextField fullWidth label="Location" value={newEvent.location} onChange={e => setNewEvent({ ...newEvent, location: e.target.value })} />
                        <TextField fullWidth multiline rows={3} label="Description" value={newEvent.description} onChange={e => setNewEvent({ ...newEvent, description: e.target.value })} />
                    </Stack>
                </DialogContent>
                <DialogActions sx={{ p: 3 }}>
                    <Button onClick={() => setOpenEvent(false)} sx={{ fontWeight: 800 }}>Cancel</Button>
                    <Button onClick={handleAddEvent} variant="contained" sx={{ borderRadius: 2, fontWeight: 900, background: GRADIENTS.success }}>Add Event</Button>
                </DialogActions>
            </Dialog>

            {/* Document Upload */}
            <Dialog open={openDoc} onClose={() => setOpenDoc(false)} maxWidth="sm" fullWidth
                PaperProps={{ sx: { background: isDark ? "rgba(15,23,42,0.95)" : "rgba(255,255,255,0.98)", backdropFilter: "blur(20px)", borderRadius: 4 } }}>
                <DialogTitle fontWeight={1000}>Upload Department Document</DialogTitle>
                <DialogContent>
                    <Stack spacing={2.5} sx={{ mt: 1 }}>
                        <TextField fullWidth label="Document Name" value={newDoc.name} onChange={e => setNewDoc({ ...newDoc, name: e.target.value })} />
                        <TextField select fullWidth label="Document Type" value={newDoc.type} onChange={e => setNewDoc({ ...newDoc, type: e.target.value })}>
                            {Object.keys(DOC_ICONS).map(t => <MenuItem key={t} value={t}>{t.charAt(0).toUpperCase() + t.slice(1)}</MenuItem>)}
                        </TextField>
                        <TextField fullWidth multiline rows={2} label="Description (optional)" value={newDoc.description} onChange={e => setNewDoc({ ...newDoc, description: e.target.value })} />
                        <Box sx={{ border: "2px dashed", borderColor: "divider", borderRadius: 3, p: 4, textAlign: "center" }}>
                            <UploadFile sx={{ fontSize: 40, color: "text.secondary", opacity: 0.4, mb: 1 }} />
                            <Typography variant="body2" color="text.secondary" fontWeight={700}>Click to select file or drag and drop</Typography>
                            <Typography variant="caption" color="text.secondary">PDF, DOC, XLSX supported</Typography>
                        </Box>
                    </Stack>
                </DialogContent>
                <DialogActions sx={{ p: 3 }}>
                    <Button onClick={() => setOpenDoc(false)} sx={{ fontWeight: 800 }}>Cancel</Button>
                    <Button onClick={handleAddDoc} variant="contained" sx={{ borderRadius: 2, fontWeight: 900, background: GRADIENTS.secondary }}>
                        Upload
                    </Button>
                </DialogActions>
            </Dialog>

            {/* Room Booking */}
            <Dialog open={openBooking} onClose={() => setOpenBooking(false)} maxWidth="sm" fullWidth
                PaperProps={{ sx: { background: isDark ? "rgba(15,23,42,0.95)" : "rgba(255,255,255,0.98)", backdropFilter: "blur(20px)", borderRadius: 4 } }}>
                <DialogTitle fontWeight={1000}>Book Room / Lab</DialogTitle>
                <DialogContent>
                    <Stack spacing={2.5} sx={{ mt: 1 }}>
                        <TextField fullWidth label="Room / Venue" placeholder="e.g. Lab 3, Hall B" value={newBooking.room} onChange={e => setNewBooking({ ...newBooking, room: e.target.value })} />
                        <TextField fullWidth type="date" label="Date" InputLabelProps={{ shrink: true }} value={newBooking.date} onChange={e => setNewBooking({ ...newBooking, date: e.target.value })} />
                        <Grid container spacing={2}>
                            <Grid item xs={6}><TextField select fullWidth label="Start" value={newBooking.startTime} onChange={e => setNewBooking({ ...newBooking, startTime: e.target.value })}>
                                {["08:00", "09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00"].map(t => <MenuItem key={t} value={t}>{t}</MenuItem>)}
                            </TextField></Grid>
                            <Grid item xs={6}><TextField select fullWidth label="End" value={newBooking.endTime} onChange={e => setNewBooking({ ...newBooking, endTime: e.target.value })}>
                                {["09:00", "10:00", "11:00", "12:00", "13:00", "14:00", "15:00", "16:00", "17:00", "18:00"].map(t => <MenuItem key={t} value={t}>{t}</MenuItem>)}
                            </TextField></Grid>
                        </Grid>
                        <TextField fullWidth label="Purpose" value={newBooking.purpose} onChange={e => setNewBooking({ ...newBooking, purpose: e.target.value })} />
                    </Stack>
                </DialogContent>
                <DialogActions sx={{ p: 3 }}>
                    <Button onClick={() => setOpenBooking(false)} sx={{ fontWeight: 800 }}>Cancel</Button>
                    <Button onClick={handleAddBooking} variant="contained" sx={{ borderRadius: 2, fontWeight: 900, background: GRADIENTS.premium }}>Confirm Booking</Button>
                </DialogActions>
            </Dialog>

            {/* Equipment */}
            <Dialog open={openEquip} onClose={() => setOpenEquip(false)} maxWidth="xs" fullWidth
                PaperProps={{ sx: { background: isDark ? "rgba(15,23,42,0.95)" : "rgba(255,255,255,0.98)", backdropFilter: "blur(20px)", borderRadius: 4 } }}>
                <DialogTitle fontWeight={1000}>Add Equipment</DialogTitle>
                <DialogContent>
                    <Stack spacing={2.5} sx={{ mt: 1 }}>
                        <TextField fullWidth label="Equipment Name" value={newEquip.name} onChange={e => setNewEquip({ ...newEquip, name: e.target.value })} />
                        <TextField select fullWidth label="Type" value={newEquip.type} onChange={e => setNewEquip({ ...newEquip, type: e.target.value })}>
                            {["Computer", "Projector", "Lab Instrument", "Printer", "Server", "Other"].map(t => <MenuItem key={t} value={t}>{t}</MenuItem>)}
                        </TextField>
                        <TextField fullWidth label="Location" value={newEquip.location} onChange={e => setNewEquip({ ...newEquip, location: e.target.value })} />
                        <TextField select fullWidth label="Status" value={newEquip.status} onChange={e => setNewEquip({ ...newEquip, status: e.target.value })}>
                            <MenuItem value="Available">Available</MenuItem>
                            <MenuItem value="In Use">In Use</MenuItem>
                            <MenuItem value="Under Maintenance">Under Maintenance</MenuItem>
                        </TextField>
                    </Stack>
                </DialogContent>
                <DialogActions sx={{ p: 3 }}>
                    <Button onClick={() => setOpenEquip(false)} sx={{ fontWeight: 800 }}>Cancel</Button>
                    <Button onClick={handleAddEquip} variant="contained" sx={{ borderRadius: 2, fontWeight: 900, background: GRADIENTS.success }}>Add</Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
}

import React, { useState, useEffect } from "react";
import {
    Box, Grid, Card, CardContent, Typography, Button, Chip, Stack, Avatar,
    Dialog, DialogTitle, DialogContent, DialogActions, TextField, MenuItem,
    Table, TableBody, TableCell, TableContainer, TableHead, TableRow,
    IconButton, Tabs, Tab, Divider, alpha, LinearProgress,
    Select, FormControl, InputLabel,
} from "@mui/material";
import {
    Grade, CheckCircle, PendingActions, Send, Refresh,
    Add as AddIcon, Close as CloseIcon, School, TrendingUp,
    Assignment, ThumbUp, ThumbDown, Warning as WarningIcon,
    Download, Assessment,
} from "@mui/icons-material";
import { useTheme } from "@mui/material/styles";
import {
    BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip as RechartsTooltip,
    ResponsiveContainer, Cell, PieChart, Pie, Legend,
} from "recharts";
import { enrollmentsAPI } from "../../../services/api";

const GRADIENTS = {
    premium: "linear-gradient(135deg, #2563eb 0%, #7c3aed 100%)",
    success: "linear-gradient(135deg, #10b981 0%, #059669 100%)",
    warning: "linear-gradient(135deg, #f59e0b 0%, #d97706 100%)",
    danger: "linear-gradient(135deg, #ef4444 0%, #dc2626 100%)",
};

const GRADE_OPTIONS = ["A", "A-", "B+", "B", "B-", "C+", "C", "D", "F", "IN", "W"];
const GPA_MAP = { A: 4.0, "A-": 3.7, "B+": 3.3, B: 3.0, "B-": 2.7, "C+": 2.3, C: 2.0, D: 1.0, F: 0.0, IN: null, W: null };

function gradeColor(grade) {
    if (!grade || grade === "N/A") return "#94a3b8";
    if (["A", "A-"].includes(grade)) return "#10b981";
    if (["B+", "B", "B-"].includes(grade)) return "#6366f1";
    if (["C+", "C"].includes(grade)) return "#f59e0b";
    if (grade === "D") return "#f97316";
    if (grade === "F") return "#ef4444";
    return "#94a3b8";
}

const RUBRIC_TEMPLATES = [
    { id: 1, name: "Midterm Exam Rubric", criteria: ["Content Knowledge (40%)", "Problem Solving (30%)", "Presentation (20%)", "References (10%)"] },
    { id: 2, name: "Assignment Rubric", criteria: ["Completeness (30%)", "Accuracy (40%)", "Formatting (20%)", "Originality (10%)"] },
    { id: 3, name: "Project Report Rubric", criteria: ["Introduction (15%)", "Methodology (25%)", "Results (30%)", "Discussion (20%)", "Conclusion (10%)"] },
];

export default function GradingTab({ courses, user, department }) {
    const theme = useTheme();
    const isDark = theme.palette.mode === "dark";
    const [activeSubTab, setActiveSubTab] = useState(0);
    const [selectedCourse, setSelectedCourse] = useState("");
    const [enrollments, setEnrollments] = useState([]);
    const [allEnrollments, setAllEnrollments] = useState([]);
    const [openGradeModal, setOpenGradeModal] = useState(false);
    const [selectedEnr, setSelectedEnr] = useState(null);
    const [tempGrade, setTempGrade] = useState("");
    const [openRubric, setOpenRubric] = useState(false);
    const [openAppeal, setOpenAppeal] = useState(false);
    const [pendingApprovals, setPendingApprovals] = useState([]);

    const glass = {
        background: isDark ? "rgba(15,23,42,0.6)" : "rgba(255,255,255,0.85)",
        backdropFilter: "blur(20px)",
        border: isDark ? "1px solid rgba(255,255,255,0.08)" : "1px solid rgba(255,255,255,0.5)",
        borderRadius: 16,
    };

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => { fetchAllEnrollments(); }, [department]);

    // eslint-disable-next-line react-hooks/exhaustive-deps
    useEffect(() => {
        if (selectedCourse) fetchCourseEnrollments(selectedCourse);
    }, [selectedCourse]);

    const fetchAllEnrollments = async () => {
        try {
            const res = await enrollmentsAPI.getAll({ department });
            const data = res.data || [];
            setAllEnrollments(data);
            setPendingApprovals(data.filter(e => e.gradeStatus === "submitted" || e.gradeStatus === "pending_approval"));
        } catch (e) { console.error(e); }
    };

    const fetchCourseEnrollments = async (courseId) => {
        try {
            const res = await enrollmentsAPI.getAll({ courseId });
            setEnrollments(res.data || []);
        } catch (e) { console.error(e); }
    };

    const handleSaveGrade = async () => {
        if (!selectedEnr || !tempGrade) return;
        try {
            await enrollmentsAPI.update(selectedEnr._id || selectedEnr.id, {
                grade: tempGrade,
                gradeStatus: "submitted",
                gradedAt: new Date().toISOString(),
                gradedBy: user?._id || user?.uid,
            });
            setOpenGradeModal(false);
            setTempGrade("");
            fetchCourseEnrollments(selectedCourse);
        } catch (e) { console.error(e); }
    };

    const handleApproveGrade = async (enrId) => {
        try {
            await enrollmentsAPI.update(enrId, { gradeStatus: "approved", approvedBy: user?._id || user?.uid, approvedAt: new Date().toISOString() });
            fetchAllEnrollments();
        } catch (e) { console.error(e); }
    };

    const handleForwardToRegistrar = async () => {
        try {
            const approved = allEnrollments.filter(e => e.gradeStatus === "approved");
            for (const enr of approved) {
                await enrollmentsAPI.update(enr._id, { gradeStatus: "forwarded_to_registrar" });
            }
            fetchAllEnrollments();
            alert(`${approved.length} grade records forwarded to Registrar.`);
        } catch (e) { console.error(e); }
    };

    // Grade distribution data for chart
    const gradeDistribution = GRADE_OPTIONS.filter(g => !["IN", "W"].includes(g)).map(grade => ({
        grade,
        count: enrollments.filter(e => e.grade === grade).length,
        fill: gradeColor(grade),
    })).filter(d => d.count > 0);

    // GPA computation
    const computeStudentGPA = (studentId) => {
        const studentEnrs = allEnrollments.filter(e => e.studentId === studentId && e.grade && GPA_MAP[e.grade] !== null);
        if (studentEnrs.length === 0) return null;
        const sum = studentEnrs.reduce((acc, e) => acc + (GPA_MAP[e.grade] || 0), 0);
        return (sum / studentEnrs.length).toFixed(2);
    };

    const gradeAppeals = [
        { id: 1, studentName: "Sara Mohammed", courseCode: "CS301", currentGrade: "C+", requestedGrade: "B-", reason: "Midterm calculation error", date: "2026-06-01" },
        { id: 2, studentName: "Khalid Ali", courseCode: "MATH201", currentGrade: "D", requestedGrade: "C", reason: "Final exam attendance not counted", date: "2026-05-30" },
    ];

    const subTabs = ["Gradebook", "HOD Approval Queue", "Grade Appeals", "GPA Overview", "Rubric Templates"];

    return (
        <Box>
            <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "center", mb: 4 }}>
                <Box>
                    <Typography variant="h5" fontWeight={1000} sx={{ letterSpacing: -0.5 }}>Grading & Assessment</Typography>
                    <Typography variant="caption" color="text.secondary" fontWeight={800}>
                        GRADE MANAGEMENT • APPROVAL WORKFLOW • GPA TRACKING
                    </Typography>
                </Box>
                <Button variant="contained" startIcon={<Send />} onClick={handleForwardToRegistrar}
                    sx={{ borderRadius: 2.5, fontWeight: 900, textTransform: "none", background: GRADIENTS.premium }}>
                    Forward Approved to Registrar
                </Button>
            </Box>

            <Tabs value={activeSubTab} onChange={(_, v) => setActiveSubTab(v)} sx={{
                mb: 3,
                "& .MuiTabs-indicator": { height: 3, borderRadius: 2 },
                "& .MuiTab-root": { fontWeight: 800, textTransform: "none", fontSize: "0.85rem" }
            }}>
                {subTabs.map((t, i) => (
                    <Tab key={i} label={i === 1 ? `${t} (${pendingApprovals.length})` : t} />
                ))}
            </Tabs>

            {/* Gradebook */}
            {activeSubTab === 0 && (
                <Box>
                    <Box sx={{ mb: 3, display: "flex", gap: 2, alignItems: "center" }}>
                        <TextField select label="Select Course" value={selectedCourse}
                            onChange={e => setSelectedCourse(e.target.value)} sx={{ minWidth: 300 }}>
                            {courses.map(c => <MenuItem key={c._id} value={c._id}>{c.code} — {c.name}</MenuItem>)}
                        </TextField>
                        {selectedCourse && (
                            <Chip label={`${enrollments.length} students`} sx={{ fontWeight: 900, bgcolor: alpha("#6366f1", 0.1), color: "#6366f1" }} />
                        )}
                    </Box>

                    {selectedCourse && (
                        <Grid container spacing={3}>
                            <Grid item xs={12} lg={8}>
                                <Card sx={{ ...glass }}>
                                    <CardContent sx={{ p: 3 }}>
                                        <Typography variant="h6" fontWeight={900} gutterBottom>Student Gradebook</Typography>
                                        {enrollments.length > 0 ? (
                                            <TableContainer>
                                                <Table size="small">
                                                    <TableHead>
                                                        <TableRow>
                                                            <TableCell sx={{ fontWeight: 900 }}>Student</TableCell>
                                                            <TableCell align="center" sx={{ fontWeight: 900 }}>Grade</TableCell>
                                                            <TableCell align="center" sx={{ fontWeight: 900 }}>Status</TableCell>
                                                            <TableCell align="center" sx={{ fontWeight: 900 }}>GPA Points</TableCell>
                                                            <TableCell align="right" sx={{ fontWeight: 900 }}>Actions</TableCell>
                                                        </TableRow>
                                                    </TableHead>
                                                    <TableBody>
                                                        {enrollments.map(enr => (
                                                            <TableRow key={enr._id || enr.id} sx={{ "&:hover": { bgcolor: alpha("#fff", 0.01) } }}>
                                                                <TableCell>
                                                                    <Box sx={{ display: "flex", alignItems: "center", gap: 1.5 }}>
                                                                        <Avatar sx={{ width: 32, height: 32, fontSize: "0.8rem", background: GRADIENTS.premium }}>
                                                                            {enr.studentName?.[0] || "S"}
                                                                        </Avatar>
                                                                        <Box>
                                                                            <Typography variant="body2" fontWeight={800}>{enr.studentName || "Student"}</Typography>
                                                                            <Typography variant="caption" color="text.secondary">{enr.studentId?.slice(-6) || enr.userId?.slice(-6)}</Typography>
                                                                        </Box>
                                                                    </Box>
                                                                </TableCell>
                                                                <TableCell align="center">
                                                                    <Chip label={enr.grade || "N/A"} size="small" sx={{
                                                                        fontWeight: 900, bgcolor: alpha(gradeColor(enr.grade), 0.1), color: gradeColor(enr.grade),
                                                                    }} />
                                                                </TableCell>
                                                                <TableCell align="center">
                                                                    <Chip label={(enr.gradeStatus || "not_graded").replace(/_/g, " ").toUpperCase()}
                                                                        size="small" sx={{
                                                                            fontWeight: 900, fontSize: "0.6rem",
                                                                            bgcolor: enr.gradeStatus === "approved" ? alpha("#10b981", 0.1) :
                                                                                enr.gradeStatus === "submitted" ? alpha("#f59e0b", 0.1) : alpha("#94a3b8", 0.1),
                                                                            color: enr.gradeStatus === "approved" ? "#10b981" :
                                                                                enr.gradeStatus === "submitted" ? "#f59e0b" : "#94a3b8"
                                                                        }} />
                                                                </TableCell>
                                                                <TableCell align="center">
                                                                    <Typography variant="body2" fontWeight={900} color={enr.grade ? gradeColor(enr.grade) : "text.secondary"}>
                                                                        {enr.grade && GPA_MAP[enr.grade] !== null ? GPA_MAP[enr.grade]?.toFixed(1) : "—"}
                                                                    </Typography>
                                                                </TableCell>
                                                                <TableCell align="right">
                                                                    <Button size="small" onClick={() => { setSelectedEnr(enr); setTempGrade(enr.grade || ""); setOpenGradeModal(true); }}
                                                                        sx={{ fontWeight: 800, textTransform: "none" }}>
                                                                        {enr.grade ? "Update" : "Grade"}
                                                                    </Button>
                                                                </TableCell>
                                                            </TableRow>
                                                        ))}
                                                    </TableBody>
                                                </Table>
                                            </TableContainer>
                                        ) : (
                                            <Box sx={{ py: 6, textAlign: "center" }}>
                                                <School sx={{ fontSize: 48, color: "text.secondary", opacity: 0.2, mb: 2 }} />
                                                <Typography color="text.secondary">No students enrolled in this course</Typography>
                                            </Box>
                                        )}
                                    </CardContent>
                                </Card>
                            </Grid>

                            {/* Grade Distribution Chart */}
                            <Grid item xs={12} lg={4}>
                                <Card sx={{ ...glass }}>
                                    <CardContent sx={{ p: 3 }}>
                                        <Typography variant="h6" fontWeight={900} gutterBottom>Grade Distribution</Typography>
                                        {gradeDistribution.length > 0 ? (
                                            <Box sx={{ height: 280 }}>
                                                <ResponsiveContainer width="100%" height="100%">
                                                    <BarChart data={gradeDistribution}>
                                                        <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={alpha("#94a3b8", 0.1)} />
                                                        <XAxis dataKey="grade" axisLine={false} tickLine={false} tick={{ fontWeight: 700, fontSize: 12 }} />
                                                        <YAxis axisLine={false} tickLine={false} tick={{ fontWeight: 700, fontSize: 12 }} />
                                                        <RechartsTooltip contentStyle={{ borderRadius: 12, border: "none" }} />
                                                        <Bar dataKey="count" radius={[6, 6, 0, 0]} barSize={28}>
                                                            {gradeDistribution.map((entry, i) => <Cell key={i} fill={entry.fill} />)}
                                                        </Bar>
                                                    </BarChart>
                                                </ResponsiveContainer>
                                            </Box>
                                        ) : (
                                            <Box sx={{ py: 6, textAlign: "center" }}>
                                                <Assessment sx={{ fontSize: 48, color: "text.secondary", opacity: 0.2 }} />
                                                <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>Grade data will appear here</Typography>
                                            </Box>
                                        )}
                                        <Divider sx={{ my: 2 }} />
                                        <Stack spacing={1}>
                                            {[
                                                { label: "Total Students", value: enrollments.length },
                                                { label: "Graded", value: enrollments.filter(e => e.grade).length },
                                                { label: "Passed (≥C)", value: enrollments.filter(e => e.grade && !["D", "F"].includes(e.grade)).length },
                                                { label: "Failed (F/D)", value: enrollments.filter(e => ["D", "F"].includes(e.grade)).length },
                                            ].map((item, i) => (
                                                <Box key={i} sx={{ display: "flex", justifyContent: "space-between" }}>
                                                    <Typography variant="body2" color="text.secondary" fontWeight={700}>{item.label}</Typography>
                                                    <Typography variant="body2" fontWeight={900}>{item.value}</Typography>
                                                </Box>
                                            ))}
                                        </Stack>
                                    </CardContent>
                                </Card>
                            </Grid>
                        </Grid>
                    )}

                    {!selectedCourse && (
                        <Box sx={{ ...glass, p: 8, textAlign: "center" }}>
                            <Grade sx={{ fontSize: 64, color: "text.secondary", opacity: 0.2, mb: 2 }} />
                            <Typography variant="h6" color="text.secondary" fontWeight={700}>Select a course to view the gradebook</Typography>
                        </Box>
                    )}
                </Box>
            )}

            {/* HOD Approval Queue */}
            {activeSubTab === 1 && (
                <Box>
                    {pendingApprovals.length === 0 ? (
                        <Box sx={{ ...glass, p: 8, textAlign: "center" }}>
                            <CheckCircle sx={{ fontSize: 64, color: "#10b981", opacity: 0.4, mb: 2 }} />
                            <Typography variant="h6" color="text.secondary" fontWeight={700}>No pending grade approvals</Typography>
                        </Box>
                    ) : (
                        <TableContainer sx={{ ...glass }}>
                            <Table>
                                <TableHead>
                                    <TableRow>
                                        <TableCell sx={{ fontWeight: 900 }}>Student</TableCell>
                                        <TableCell sx={{ fontWeight: 900 }}>Course</TableCell>
                                        <TableCell align="center" sx={{ fontWeight: 900 }}>Grade</TableCell>
                                        <TableCell sx={{ fontWeight: 900 }}>Submitted By</TableCell>
                                        <TableCell align="right" sx={{ fontWeight: 900 }}>Actions</TableCell>
                                    </TableRow>
                                </TableHead>
                                <TableBody>
                                    {pendingApprovals.map(enr => (
                                        <TableRow key={enr._id}>
                                            <TableCell fontWeight={800}>{enr.studentName || "Student"}</TableCell>
                                            <TableCell><Chip label={enr.courseCode || enr.courseId?.slice(-6)} size="small" sx={{ fontWeight: 900 }} /></TableCell>
                                            <TableCell align="center">
                                                <Chip label={enr.grade} size="small" sx={{ fontWeight: 900, bgcolor: alpha(gradeColor(enr.grade), 0.1), color: gradeColor(enr.grade) }} />
                                            </TableCell>
                                            <TableCell sx={{ fontWeight: 700 }}>{enr.gradedByName || "Faculty"}</TableCell>
                                            <TableCell align="right">
                                                <Stack direction="row" spacing={1} justifyContent="flex-end">
                                                    <Button size="small" variant="contained" color="success" startIcon={<ThumbUp />}
                                                        onClick={() => handleApproveGrade(enr._id)}
                                                        sx={{ borderRadius: 2, fontWeight: 900, textTransform: "none" }}>Approve</Button>
                                                    <Button size="small" variant="outlined" color="error" startIcon={<ThumbDown />}
                                                        sx={{ borderRadius: 2, fontWeight: 900, textTransform: "none" }}>Return</Button>
                                                </Stack>
                                            </TableCell>
                                        </TableRow>
                                    ))}
                                </TableBody>
                            </Table>
                        </TableContainer>
                    )}
                </Box>
            )}

            {/* Grade Appeals */}
            {activeSubTab === 2 && (
                <Grid container spacing={3}>
                    {gradeAppeals.map(appeal => (
                        <Grid item xs={12} md={6} key={appeal.id}>
                            <Card sx={{ ...glass }}>
                                <CardContent sx={{ p: 3 }}>
                                    <Box sx={{ display: "flex", justifyContent: "space-between", mb: 2 }}>
                                        <Box sx={{ display: "flex", gap: 1.5, alignItems: "center" }}>
                                            <Avatar sx={{ background: GRADIENTS.warning }}>{appeal.studentName[0]}</Avatar>
                                            <Box>
                                                <Typography variant="subtitle2" fontWeight={900}>{appeal.studentName}</Typography>
                                                <Typography variant="caption" color="text.secondary">{appeal.date}</Typography>
                                            </Box>
                                        </Box>
                                        <Chip label={appeal.courseCode} size="small" sx={{ fontWeight: 900 }} />
                                    </Box>
                                    <Box sx={{ display: "flex", alignItems: "center", gap: 1, mb: 2 }}>
                                        <Chip label={appeal.currentGrade} size="small" sx={{ bgcolor: alpha(gradeColor(appeal.currentGrade), 0.1), color: gradeColor(appeal.currentGrade), fontWeight: 900 }} />
                                        <Typography variant="caption" color="text.secondary">→ requested →</Typography>
                                        <Chip label={appeal.requestedGrade} size="small" sx={{ bgcolor: alpha(gradeColor(appeal.requestedGrade), 0.1), color: gradeColor(appeal.requestedGrade), fontWeight: 900 }} />
                                    </Box>
                                    <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>{appeal.reason}</Typography>
                                    <Stack direction="row" spacing={1}>
                                        <Button size="small" variant="contained" color="success" sx={{ borderRadius: 2, fontWeight: 900, textTransform: "none" }}>
                                            Approve Appeal
                                        </Button>
                                        <Button size="small" variant="outlined" color="error" sx={{ borderRadius: 2, fontWeight: 900, textTransform: "none" }}>
                                            Reject
                                        </Button>
                                    </Stack>
                                </CardContent>
                            </Card>
                        </Grid>
                    ))}
                </Grid>
            )}

            {/* GPA Overview */}
            {activeSubTab === 3 && (
                <Grid container spacing={3}>
                    <Grid item xs={12} md={8}>
                        <Card sx={{ ...glass }}>
                            <CardContent sx={{ p: 3 }}>
                                <Typography variant="h6" fontWeight={900} gutterBottom>GPA Distribution by Course</Typography>
                                <Box sx={{ height: 300 }}>
                                    <ResponsiveContainer width="100%" height="100%">
                                        <BarChart data={courses.map(c => {
                                            const courseEnrs = allEnrollments.filter(e => e.courseId === c._id && e.grade && GPA_MAP[e.grade] !== null);
                                            const avg = courseEnrs.length > 0 ? courseEnrs.reduce((a, e) => a + (GPA_MAP[e.grade] || 0), 0) / courseEnrs.length : 0;
                                            return { name: c.code, gpa: parseFloat(avg.toFixed(2)) };
                                        })}>
                                            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke={alpha("#94a3b8", 0.1)} />
                                            <XAxis dataKey="name" tick={{ fontWeight: 700, fontSize: 12 }} axisLine={false} tickLine={false} />
                                            <YAxis domain={[0, 4]} tick={{ fontWeight: 700, fontSize: 12 }} axisLine={false} tickLine={false} />
                                            <RechartsTooltip contentStyle={{ borderRadius: 12, border: "none" }} />
                                            <Bar dataKey="gpa" radius={[6, 6, 0, 0]} barSize={36} fill="#6366f1" />
                                        </BarChart>
                                    </ResponsiveContainer>
                                </Box>
                            </CardContent>
                        </Card>
                    </Grid>
                    <Grid item xs={12} md={4}>
                        <Card sx={{ ...glass, background: GRADIENTS.premium, color: "white" }}>
                            <CardContent sx={{ p: 3 }}>
                                <Typography variant="h6" fontWeight={900} gutterBottom>Department GPA Summary</Typography>
                                <Stack spacing={2} sx={{ mt: 2 }}>
                                    {[
                                        { label: "Total Enrollments", value: allEnrollments.length },
                                        { label: "Graded Records", value: allEnrollments.filter(e => e.grade).length },
                                        { label: "A/A- Students", value: allEnrollments.filter(e => ["A", "A-"].includes(e.grade)).length },
                                        { label: "Failing Students", value: allEnrollments.filter(e => e.grade === "F").length },
                                        { label: "Incomplete (IN)", value: allEnrollments.filter(e => e.grade === "IN").length },
                                    ].map((item, i) => (
                                        <Box key={i} sx={{ display: "flex", justifyContent: "space-between", borderBottom: "1px solid rgba(255,255,255,0.1)", pb: 1 }}>
                                            <Typography variant="body2" fontWeight={700} sx={{ opacity: 0.7 }}>{item.label}</Typography>
                                            <Typography variant="body2" fontWeight={900}>{item.value}</Typography>
                                        </Box>
                                    ))}
                                </Stack>
                            </CardContent>
                        </Card>
                    </Grid>
                </Grid>
            )}

            {/* Rubric Templates */}
            {activeSubTab === 4 && (
                <Grid container spacing={3}>
                    {RUBRIC_TEMPLATES.map(rubric => (
                        <Grid item xs={12} md={4} key={rubric.id}>
                            <Card sx={{ ...glass }}>
                                <CardContent sx={{ p: 3 }}>
                                    <Box sx={{ display: "flex", gap: 1.5, mb: 2, alignItems: "center" }}>
                                        <Avatar sx={{ background: GRADIENTS.premium }}><Assignment /></Avatar>
                                        <Typography variant="subtitle1" fontWeight={900}>{rubric.name}</Typography>
                                    </Box>
                                    <Stack spacing={1}>
                                        {rubric.criteria.map((cr, i) => (
                                            <Box key={i} sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                                                <Box sx={{ width: 6, height: 6, borderRadius: "50%", bgcolor: "#6366f1" }} />
                                                <Typography variant="body2" fontWeight={700}>{cr}</Typography>
                                            </Box>
                                        ))}
                                    </Stack>
                                    <Button fullWidth variant="outlined" sx={{ mt: 3, borderRadius: 2.5, fontWeight: 800, textTransform: "none" }}>
                                        Use Template
                                    </Button>
                                </CardContent>
                            </Card>
                        </Grid>
                    ))}
                    <Grid item xs={12} md={4}>
                        <Card sx={{ ...glass, border: "2px dashed", borderColor: "divider" }}>
                            <CardContent sx={{ p: 3, textAlign: "center", py: 6 }}>
                                <AddIcon sx={{ fontSize: 40, color: "text.secondary", opacity: 0.4, mb: 1 }} />
                                <Typography variant="subtitle1" fontWeight={900} color="text.secondary">New Rubric Template</Typography>
                                <Button variant="outlined" sx={{ mt: 2, borderRadius: 2.5, fontWeight: 800, textTransform: "none" }}>
                                    Create Template
                                </Button>
                            </CardContent>
                        </Card>
                    </Grid>
                </Grid>
            )}

            {/* Grade Entry Dialog */}
            <Dialog open={openGradeModal} onClose={() => setOpenGradeModal(false)} maxWidth="xs" fullWidth
                PaperProps={{ sx: { background: isDark ? "rgba(15,23,42,0.95)" : "rgba(255,255,255,0.98)", backdropFilter: "blur(20px)", borderRadius: 4 } }}>
                <DialogTitle fontWeight={1000}>
                    {selectedEnr?.grade ? "Update Grade" : "Enter Grade"}: {selectedEnr?.studentName || "Student"}
                </DialogTitle>
                <DialogContent>
                    <TextField select fullWidth label="Final Grade" value={tempGrade}
                        onChange={e => setTempGrade(e.target.value)} sx={{ mt: 2 }}>
                        {GRADE_OPTIONS.map(g => <MenuItem key={g} value={g}><Box sx={{ display: "flex", alignItems: "center", gap: 1 }}><Box sx={{ width: 12, height: 12, borderRadius: "50%", bgcolor: gradeColor(g) }} />{g}</Box></MenuItem>)}
                    </TextField>
                </DialogContent>
                <DialogActions sx={{ p: 3 }}>
                    <Button onClick={() => setOpenGradeModal(false)} sx={{ fontWeight: 800 }}>Cancel</Button>
                    <Button onClick={handleSaveGrade} variant="contained" sx={{ borderRadius: 2, fontWeight: 900, background: GRADIENTS.premium }}>
                        Save Grade
                    </Button>
                </DialogActions>
            </Dialog>
        </Box>
    );
}

import React, { useState } from "react";
import {
    Box, Grid, Card, CardContent, Typography, Chip, Stack, Avatar,
    Divider, alpha, Switch, FormControlLabel, Table, TableBody,
    TableCell, TableContainer, TableHead, TableRow, Button,
} from "@mui/material";
import {
    CheckCircle, ErrorOutline, Schedule, HelpOutline,
    Email, Sms, Notifications, School, AccountBalance,
    LocalLibrary, AttachMoney, People, VerifiedUser,
    AdminPanelSettings, SupervisorAccount, Assignment,
} from "@mui/icons-material";
import { useTheme } from "@mui/material/styles";

const GRADIENTS = {
    premium: "linear-gradient(135deg, #2563eb 0%, #7c3aed 100%)",
    success: "linear-gradient(135deg, #10b981 0%, #059669 100%)",
    warning: "linear-gradient(135deg, #f59e0b 0%, #d97706 100%)",
    secondary: "linear-gradient(135deg, #4f46e5 0%, #7c3aed 100%)",
};

const INTEGRATIONS = [
    { name: "Registrar Portal", desc: "Enrollment, transcripts, grade submission", icon: <Assignment />, status: "connected", color: "#10b981" },
    { name: "Admin Portal", desc: "HR, budget approvals, system settings", icon: <AdminPanelSettings />, status: "connected", color: "#10b981" },
    { name: "Student Portal", desc: "Grades, attendance, course registration", icon: <School />, status: "connected", color: "#10b981" },
    { name: "Lecturer Portal", desc: "Course materials, assignments, submissions", icon: <SupervisorAccount />, status: "connected", color: "#10b981" },
    { name: "College Portal", desc: "College-wide reporting and approvals", icon: <AccountBalance />, status: "connected", color: "#10b981" },
    { name: "LMS (Moodle/Blackboard)", desc: "Course content, quizzes, online classes", icon: <People />, status: "pending", color: "#f59e0b" },
    { name: "Finance System", desc: "Fee collection, budget allocation", icon: <AttachMoney />, status: "connected", color: "#10b981" },
    { name: "Library System", desc: "Resource access, book reservations", icon: <LocalLibrary />, status: "not_configured", color: "#6366f1" },
];

const STATUS_LABEL = { connected: "Connected", pending: "Pending Setup", not_configured: "Not Configured" };
const STATUS_COLORS = { connected: "#10b981", pending: "#f59e0b", not_configured: "#94a3b8" };

const NOTIFICATION_EVENTS = [
    { key: "grade_submitted", label: "Grade Submission", email: true, sms: false },
    { key: "warning_issued", label: "Academic Warning Issued", email: true, sms: true },
    { key: "graduation_cleared", label: "Graduation Clearance Approved", email: true, sms: true },
    { key: "new_student", label: "New Student Enrolled", email: true, sms: false },
    { key: "add_drop", label: "Add/Drop Request Received", email: true, sms: false },
    { key: "exam_scheduled", label: "Exam Scheduled", email: true, sms: false },
    { key: "faculty_leave", label: "Faculty Leave Requested", email: true, sms: false },
    { key: "appeal_received", label: "Grade Appeal Received", email: true, sms: true },
];

const RBAC = [
    {
        role: "HOD (Head of Department)",
        icon: <AdminPanelSettings />,
        color: "#ef4444",
        permissions: ["Full access to all tabs", "Grade approval", "Faculty management", "Budget oversight", "Accreditation documents", "Forward grades to Registrar"],
    },
    {
        role: "Faculty / Lecturer",
        icon: <School />,
        color: "#6366f1",
        permissions: ["View enrolled students", "Enter & submit grades", "View own timetable", "Upload course syllabus", "Track student attendance"],
    },
    {
        role: "Department Secretary",
        icon: <Assignment />,
        color: "#f59e0b",
        permissions: ["Manage announcements", "Book rooms/labs", "Manage event calendar", "Upload documents", "Manage meeting agendas"],
    },
    {
        role: "Academic Advisor",
        icon: <SupervisorAccount />,
        color: "#10b981",
        permissions: ["View assigned students", "Issue academic warnings", "Process graduation clearance", "Add advising notes", "View student academic progress"],
    },
];

export default function IntegrationsTab({ user }) {
    const theme = useTheme();
    const isDark = theme.palette.mode === "dark";
    const [notifications, setNotifications] = useState(
        NOTIFICATION_EVENTS.reduce((acc, e) => ({ ...acc, [e.key]: { email: e.email, sms: e.sms } }), {})
    );

    const glass = {
        background: isDark ? "rgba(15,23,42,0.6)" : "rgba(255,255,255,0.85)",
        backdropFilter: "blur(20px)",
        border: isDark ? "1px solid rgba(255,255,255,0.08)" : "1px solid rgba(255,255,255,0.5)",
        borderRadius: 16,
    };

    const toggleNotification = (key, type) => {
        setNotifications(prev => ({
            ...prev,
            [key]: { ...prev[key], [type]: !prev[key][type] },
        }));
    };

    return (
        <Box>
            <Box sx={{ mb: 4 }}>
                <Typography variant="h5" fontWeight={1000} sx={{ letterSpacing: -0.5 }}>Integration & Communication</Typography>
                <Typography variant="caption" color="text.secondary" fontWeight={800}>
                    SYSTEM CONNECTIONS • NOTIFICATIONS • ROLE-BASED ACCESS
                </Typography>
            </Box>

            {/* System Integrations */}
            <Typography variant="h6" fontWeight={900} gutterBottom>System Integrations</Typography>
            <Grid container spacing={3} sx={{ mb: 5 }}>
                {INTEGRATIONS.map((intg, i) => (
                    <Grid item xs={12} sm={6} md={3} key={i}>
                        <Card sx={{ ...glass, transition: "0.3s", "&:hover": { transform: "translateY(-4px)" } }}>
                            <CardContent sx={{ p: 3 }}>
                                <Box sx={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start", mb: 2 }}>
                                    <Avatar sx={{ background: GRADIENTS.premium, width: 44, height: 44 }}>
                                        {intg.icon}
                                    </Avatar>
                                    <Box sx={{ display: "flex", alignItems: "center", gap: 0.5 }}>
                                        <Box sx={{
                                            width: 8, height: 8, borderRadius: "50%", bgcolor: STATUS_COLORS[intg.status],
                                            boxShadow: intg.status === "connected" ? `0 0 8px ${STATUS_COLORS[intg.status]}` : "none"
                                        }} />
                                        <Chip label={STATUS_LABEL[intg.status]} size="small" sx={{
                                            fontWeight: 900, fontSize: "0.6rem",
                                            bgcolor: alpha(STATUS_COLORS[intg.status], 0.1), color: STATUS_COLORS[intg.status]
                                        }} />
                                    </Box>
                                </Box>
                                <Typography variant="subtitle2" fontWeight={900}>{intg.name}</Typography>
                                <Typography variant="caption" color="text.secondary">{intg.desc}</Typography>
                                {intg.status !== "connected" && (
                                    <Button fullWidth variant="outlined" size="small" sx={{ mt: 2, borderRadius: 2, fontWeight: 800, textTransform: "none" }}>
                                        {intg.status === "pending" ? "Complete Setup" : "Configure"}
                                    </Button>
                                )}
                            </CardContent>
                        </Card>
                    </Grid>
                ))}
            </Grid>

            {/* Summary */}
            <Grid container spacing={2} sx={{ mb: 5 }}>
                {[
                    { label: "Connected", count: INTEGRATIONS.filter(i => i.status === "connected").length, color: "#10b981" },
                    { label: "Pending", count: INTEGRATIONS.filter(i => i.status === "pending").length, color: "#f59e0b" },
                    { label: "Not Configured", count: INTEGRATIONS.filter(i => i.status === "not_configured").length, color: "#94a3b8" },
                ].map((s, i) => (
                    <Grid item xs={4} key={i}>
                        <Card sx={{ ...glass }}>
                            <CardContent sx={{ p: 2, textAlign: "center" }}>
                                <Typography variant="h4" fontWeight={1000} color={s.color}>{s.count}</Typography>
                                <Typography variant="caption" color="text.secondary" fontWeight={800}>{s.label}</Typography>
                            </CardContent>
                        </Card>
                    </Grid>
                ))}
            </Grid>

            {/* Notification Settings */}
            <Typography variant="h6" fontWeight={900} gutterBottom>Email & SMS Notification Settings</Typography>
            <Card sx={{ ...glass, mb: 5 }}>
                <CardContent sx={{ p: 3 }}>
                    <TableContainer>
                        <Table size="small">
                            <TableHead>
                                <TableRow>
                                    <TableCell sx={{ fontWeight: 900 }}>Event</TableCell>
                                    <TableCell align="center" sx={{ fontWeight: 900 }}>
                                        <Box sx={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 0.5 }}>
                                            <Email sx={{ fontSize: 16 }} /> Email
                                        </Box>
                                    </TableCell>
                                    <TableCell align="center" sx={{ fontWeight: 900 }}>
                                        <Box sx={{ display: "flex", alignItems: "center", justifyContent: "center", gap: 0.5 }}>
                                            <Sms sx={{ fontSize: 16 }} /> SMS
                                        </Box>
                                    </TableCell>
                                </TableRow>
                            </TableHead>
                            <TableBody>
                                {NOTIFICATION_EVENTS.map(ev => (
                                    <TableRow key={ev.key}>
                                        <TableCell>
                                            <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                                                <Notifications sx={{ fontSize: 16, color: "text.secondary" }} />
                                                <Typography variant="body2" fontWeight={700}>{ev.label}</Typography>
                                            </Box>
                                        </TableCell>
                                        <TableCell align="center">
                                            <Switch size="small" checked={notifications[ev.key]?.email || false}
                                                onChange={() => toggleNotification(ev.key, "email")}
                                                sx={{ "& .MuiSwitch-thumb": { boxShadow: "none" }, "& .Mui-checked .MuiSwitch-thumb": { bgcolor: "#10b981" } }}
                                            />
                                        </TableCell>
                                        <TableCell align="center">
                                            <Switch size="small" checked={notifications[ev.key]?.sms || false}
                                                onChange={() => toggleNotification(ev.key, "sms")}
                                                sx={{ "& .Mui-checked .MuiSwitch-thumb": { bgcolor: "#6366f1" } }}
                                            />
                                        </TableCell>
                                    </TableRow>
                                ))}
                            </TableBody>
                        </Table>
                    </TableContainer>
                </CardContent>
            </Card>

            {/* RBAC */}
            <Typography variant="h6" fontWeight={900} gutterBottom>Role-Based Access Control (RBAC)</Typography>
            <Grid container spacing={3}>
                {RBAC.map((role, i) => (
                    <Grid item xs={12} md={6} key={i}>
                        <Card sx={{ ...glass }}>
                            <CardContent sx={{ p: 3 }}>
                                <Box sx={{ display: "flex", gap: 2, alignItems: "center", mb: 2 }}>
                                    <Avatar sx={{ bgcolor: alpha(role.color, 0.15), color: role.color, width: 48, height: 48 }}>
                                        {role.icon}
                                    </Avatar>
                                    <Box>
                                        <Typography variant="subtitle1" fontWeight={900}>{role.role}</Typography>
                                        <Chip label="ACTIVE ROLE" size="small" sx={{ fontWeight: 900, fontSize: "0.6rem", bgcolor: alpha(role.color, 0.1), color: role.color }} />
                                    </Box>
                                </Box>
                                <Divider sx={{ my: 1.5, opacity: 0.1 }} />
                                <Stack spacing={0.8}>
                                    {role.permissions.map((perm, pi) => (
                                        <Box key={pi} sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                                            <CheckCircle sx={{ fontSize: 14, color: role.color }} />
                                            <Typography variant="caption" fontWeight={700}>{perm}</Typography>
                                        </Box>
                                    ))}
                                </Stack>
                            </CardContent>
                        </Card>
                    </Grid>
                ))}
            </Grid>
        </Box>
    );
}

